INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('733fa7c5-700d-418e-bcdd-64afe020bf3f', 'Era of the Unpronounceable', 7, 'ERA', NULL, 'Concepts begin to take shape; different peoples spread beneath the earth. An era defined by the conflict between individuation and union.', '2026-06-23 18:54:04.38277+00', '2026-06-23 18:54:04.38277+00', 'en', '733fa7c5-700d-418e-bcdd-64afe020bf3f');
