INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('af4bc3ba-5848-4c59-bceb-576f5528f939', 'Era of Symbols', 9, 'ERA', NULL, 'An empire of unpronounceable concepts emerges, refusing to accept divine authority.', '2026-06-23 18:54:04.418364+00', '2026-06-23 18:54:04.418364+00', 'en', 'af4bc3ba-5848-4c59-bceb-576f5528f939');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('98706f60-12d5-40a0-8291-ecfa3dfb9d5c', 'Death of Jung Blackheart, Chief Resister', 10, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.450108+00', '2026-06-23 18:54:04.450108+00', 'en', '98706f60-12d5-40a0-8291-ecfa3dfb9d5c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('ec1a7fa1-7316-47df-9689-f7a65359cc87', 'Era of Forms', 11, 'ERA', NULL, 'Concepts cross the Black Lake and begin to take shape before the light of truth.', '2026-06-23 18:54:04.462402+00', '2026-06-23 18:54:04.462402+00', 'en', 'ec1a7fa1-7316-47df-9689-f7a65359cc87');
