INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('f583b008-820b-4a1a-8f41-35f90725042e', 'Era of Monads', 15, 'ERA', NULL, 'Concepts now migrate in search of another home, learning to grow on their own.', '2026-06-23 18:54:04.515353+00', '2026-06-23 18:54:04.515353+00', 'en', 'f583b008-820b-4a1a-8f41-35f90725042e');
