INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('8c57f579-e96a-41e4-821e-ee325c91384a', 'Era of the Platiad', 17, 'ERA', NULL, 'Concepts migrate into the Black Lake, and an era of intellect prevails.', '2026-06-23 18:54:04.731718+00', '2026-06-23 18:54:04.731718+00', 'en', '8c57f579-e96a-41e4-821e-ee325c91384a');
