INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('bbfd36f0-8c02-414b-bf65-6377c9cd6d45', 'Era of Platinum', 31, 'ERA', NULL, 'Magic becomes centralised in a single city. Around the world, peoples wither.', '2026-06-23 18:54:05.107687+00', '2026-06-23 18:54:05.107687+00', 'en', 'bbfd36f0-8c02-414b-bf65-6377c9cd6d45');
