INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('6f12e68d-ad71-4c51-8e80-942f8191fdda', 'Era dos Vislumbres', 5, 'ERA', NULL, 'Sob uma montanha, emergem os primeiros conceitos.', '2026-06-23 18:54:04.164302+00', '2026-06-23 18:54:04.164302+00', 'pt', '47eb040e-b0d3-492a-8817-525a91705240');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('6ebf388a-12b8-451d-83a7-c29c4c1c696c', 'A Fuga de Dot', 6, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.368255+00', '2026-06-23 18:54:04.368255+00', 'pt', 'b8b2d895-402d-4a88-a689-6b418ed0384c');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b0666803-2368-4aa2-b8b9-d009f73af809', 'Era do Impronunciável', 7, 'ERA', NULL, 'Os conceitos começam a tomar forma; diferentes povos se espalham sob a terra. Uma era definida pelo conflito entre individuação e união.', '2026-06-23 18:54:04.38277+00', '2026-06-23 18:54:04.38277+00', 'pt', '733fa7c5-700d-418e-bcdd-64afe020bf3f');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('2a8791a0-a8d3-4465-91c7-40ad270fc60f', 'Vitória do Povo dos Símbolos', 8, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.399434+00', '2026-06-23 18:54:04.399434+00', 'pt', '2c26e128-ea8d-4910-9d2d-9de56aca40cf');
