INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('681bb88e-e884-4668-83e6-db068f18b5df', 'Morte de Jung Coração-Negro, Chefe da Resistência', 10, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.450108+00', '2026-06-23 18:54:04.450108+00', 'pt', '98706f60-12d5-40a0-8291-ecfa3dfb9d5c');
