INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('747bfdd2-8ec9-4416-976d-4051bf90276b', 'Era da Lei', 43, 'ERA', NULL, 'O estudo do armamento militar decola, e uma nova onda de conquista começa entre as nações mais avançadas.', '2026-06-23 18:54:05.651498+00', '2026-06-23 18:54:05.651498+00', 'pt', '2eff7424-b158-43f9-a8a7-8992b3042295');
