INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('02bd0af8-0338-4a2b-a6c3-1fffffa451aa', 'Rebelião das Máquinas', 46, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.695639+00', '2026-06-23 18:54:05.695639+00', 'pt', '34ca791f-6c98-4262-87d7-4b8abf13f328');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('7aba3c3a-c576-4efa-8684-c068177e0f3e', 'Era dos Encontros', 47, 'ERA', NULL, 'Diversas civilizações são destruídas; outras avançam ao nível de viagens interplanetárias.', '2026-06-23 18:54:05.708094+00', '2026-06-23 18:54:05.708094+00', 'pt', '13bd8972-a1c3-4e37-82b1-6f05e4040566');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('f39e3ec0-09d1-41ae-bef5-ff27b5ef36ba', 'Catástrofe Intergaláctica', 48, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.719254+00', '2026-06-23 18:54:05.719254+00', 'pt', '83d1b21c-8399-43e3-99dc-0068d116c9a8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('3fdc7efb-17d8-4575-8106-146953843f09', 'Era da Poeira', 49, 'ERA', NULL, 'O mundo vive um cenário pós-apocalíptico; a falta de recursos aproxima cada vez mais a sociedade de seu fim.', '2026-06-23 18:54:05.732025+00', '2026-06-23 18:54:05.732025+00', 'pt', 'ff3d5bed-6438-4fdb-8919-0a41250ff71e');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('93d9c0e6-e254-44ea-85ae-b703bcce06bd', 'Começa a Guerra dos Hexágonos', 50, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.742603+00', '2026-06-23 18:54:05.742603+00', 'pt', '659fdc07-604a-46b1-aa0e-133d7e54e5b8');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('cdaf8525-4ad7-4952-b93e-5fef4066aa0c', 'Era da Morte', 51, 'ERA', NULL, 'O mundo é assolado por conflitos constantes e marcha rumo ao seu fim.', '2026-06-23 18:54:05.914423+00', '2026-06-23 18:54:05.914423+00', 'pt', 'fd791fd4-6951-4fa8-957e-5979bff9427f');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b28c235a-0c6a-4b3d-9cf8-518eeec63559', 'Fim dos Mortais', 52, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.928631+00', '2026-06-23 18:54:05.928631+00', 'pt', 'f4f343d5-9208-45f9-b7d4-3debe69443da');
INSERT INTO public.eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('36d5e2a5-be00-456b-bf11-113c0b737904', 'Era Primordial', 1, 'ERA', NULL, 'A era anterior à existência do mundo material — um tempo de pura essência, forças divinas e o alicerce sobre o qual toda a existência viria a ser construída. Nenhum mundo navegável existe aqui; apenas o infinito.', '2026-06-23 18:54:04.047617+00', '2026-06-24 02:31:11.341815+00', 'pt', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
INSERT INTO public.map_eras (map_id, era_id) VALUES ('primordial-map', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
INSERT INTO public.map_eras (map_id, era_id) VALUES ('primordial-map', '36d5e2a5-be00-456b-bf11-113c0b737904');
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('b3e2c1d4-f5e6-4a7b-8c9d-0e1f2a3b4c5d', 'Omnia', 'The final word of all things, Omnia stands at the uttermost edge of becoming — goddess of totality, dwelling in a perfection no mortal thought has reached. She is not worshipped as one among many. She is acknowledged as the bound no eye can see past, the point at which existence stops and the unimaginable begins.', '## Omnia
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('f2a029a8-0010-4864-bf3c-8ed97952a6e4', 'Khratøn', 'Khratøn, a Imperatriz de Adamantio e primeira esposa de Aleph, é uma entidade de transformação pura que não distingue criação de destruição — ambas são a mesma força, observada de pontos diferentes na sequência. É ira elementar e ação incessante, madrinha de Dixia e Trixia e mãe de Neghalem, o Negador, e age sem deliberação, imune ao remorso porque nunca separa o custo do próprio ato.', 'Khratøn é a Imperatriz de Adamantio. Foi a primeira esposa do Aleph, e é uma entidade de transformação — o que significa que ela não distingue entre o que eleva e o que destrói, porque sempre compreendeu que são o mesmo movimento, observado de pontos diferentes na sequência. A força que ergue uma muralha é a força que a derruba. A violência que despedaça o mundo é a violência que torna possível algo novo no espaço que ela abre. Khratøn não toma partido entre esses resultados. Ela fornece a força. O que ela produz é uma questão de direção.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('63beea19-161c-43cc-8a76-e6041ffeac7e', 'Ulusuros', 'Ulusuros, the Whispering Emperor, is said to be an Amet, yet his legend reads with the intimate, specific texture of a human chronicle rather than a divine myth — a hundred days at sea, a whispering sword, a betrayal, and Aleph''s power descending to strike down the sorcerer who confessed to engineering it all. Scholars who study the pantheon seriously suspect the story may be a fabrication placed into the divine canon by an unknown hand — whether to anchor an invented deity or to borrow one already real remains unknown.', 'The legend of Ulusuros, the Whispering Emperor, is not remarkable for its grandeur. It is remarkable for how precisely it is told. Every detail arrives with the specificity of a chronicle rather than the vagueness of myth: a hundred days and a hundred nights at sea, a white horse, a sword that breathed whispers through the air with every swing. A king of giants decapitated on his own throne. A counselor''s confession and a counselor''s fall. These are not the contours of a divine story. They are the contours of a human one, told with the intimacy of someone who was there.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('3c6dd2ab-b540-41a4-a4ad-2bca5e5f761c', 'Imaws', 'Imaws is the executive half of the oldest union in creation — the god who gives form to what his beloved Ælime sets in motion. If she is the impulse that wants to become, he is the hand that writes it into law. Together they fathered the Amets, the first concepts to drift through the primordial eternity, and from their twelve chosen children came every wonder and every wound the world would come to know. Imaws himself keeps to quiet, untouched places — the heart of old forests, the high silence of the mountains, the hollow behind a waterfall — a man with tired, forest-colored eyes who has been writing the world for longer than the world has existed.', 'Beneath Omnia, it is taught, there fall away a dohundred — one hundred and forty-four — layers of celestial heaven, and every one of them brims with gods past description: beings so vast and so strange that no mortal tongue has ever fixed a true name to a single one of them, and every one of them incomprehensibly powerful. And beneath all of that, deeper than the deepest of those dohundred heavens, the foundation holds two names only: Imaws, and Ælime.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('20744386-efc6-474d-aef6-27d7c4b8af33', 'Ælime', 'Ælime is the driving half of the oldest union in creation — the restlessness that wants to become, the spark that Imaws, her eternal counterpart, then gives shape and law. Her beauty is exotic and impossibly inspiring, and it is said a single glimpse of her is enough to lift joy into the heart of anyone who sees her; her mind, just as remarkable, can unravel any problem and settle any chaos into harmony. Together with Imaws she fathered the Amets, the first concepts to drift through the primordial eternity, and from their twelve chosen children came every wonder and every wound the world would come to know. Ælime herself is drawn to wherever life gathers loudest — the hottest shorelines, the most brightly lit cities, the most crowded festival — a woman with long, curling red hair, dressed as delicately as she is dazzlingly, who has been the pulse beneath the world since before the world had a pulse of its own.', 'Beneath Omnia, it is taught, there fall away a dohundred — one hundred and forty-four — layers of celestial heaven, and every one of them brims with gods past description: beings so vast and so strange that no mortal tongue has ever fixed a true name to a single one of them, and every one of them incomprehensibly powerful. And beneath all of that, deeper than the deepest of those dohundred heavens, the foundation holds two names only: Imaws, and Ælime.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('f5a61b14-e05f-4d69-880e-bc3056bbb039', 'Khratøn', 'Khratøn, the Empress of Adamantium and first wife of Aleph, is an entity of pure transformation who does not distinguish creation from destruction — both are the same force, observed from different points in the sequence. She is elemental wrath and ceaseless action, godmother to Dixia and Trixia and mother to Neghalem the Denier, and she acts without deliberation, immune to remorse because she never separates cost from the act itself.', 'Khratøn is the Empress of Adamantium. She was the first wife of Aleph, and she is an entity of transformation — which is to say that she does not distinguish between what elevates and what destroys, because she has always understood them to be the same motion, observed from different points in the sequence. The force that raises a wall is the force that brings one down. The violence that tears the world apart is the violence that makes something new possible in the space it opens. Khratøn does not take sides between these outcomes. She provides the force. What it produces is a matter of direction.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('76d64fa7-b226-4fe7-a65c-3db0f683b2c9', 'Tetros', 'The god of Stability and Balance, presiding over health, longevity, and temperance. Eternally seated in lotus, Tetros extends his immutable blessing only to those who have released the compulsion to grasp and conquer. His four arms are folded in meditation — not weakness, but strength that has chosen its own stillness.', 'Tetros is the god of Stability and of Balance. He presides over health, over longevity, and over temperance — the quiet art of knowing when enough is enough. He is found eternally seated in the lotus posture, still as stone, solid as a mountain that has never needed to justify its own weight. He asks nothing of those who approach him. He simply endures, and in his endurance he offers support to all who come seeking peace.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('32168a53-162c-4f6a-9fb9-8b3fd4cb3988', 'Trios', 'The divinity of Chaos and Movement — the restless force that refuses to let the world settle into itself. Trios holds that any balance of perfect opposites breeds only deadlock, and that a third disruptive element is needed to set true evolution in motion. Patron of beasts and instinct, he bears a bronze trident and three eyes, the third of which perceives reality stripped of all illusion.', 'Trios is the divinity of Chaos and of Movement. He is the restless energy that challenges stability in favor of evolution — the force that refuses to let the world settle into itself. To the devotees of Trios, comfort is a curse. It breeds stagnation. It breeds conformity. It is not rest, but slow death.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e5c8fc7d-1128-40ea-8da3-eb93ebcd56d5', 'Unixia', 'The goddess of the Union between the Material and Spiritual Worlds, daughter of Trios. Unixia does not reconcile the two worlds — she moves between them, and in moving makes transit possible for others. Her devotees are mystics and those who have brushed against something they could not explain, and reached toward it.', 'Unixia is the goddess of number eleven, daughter of Trios. She is the deity of the Union between the Material and Spiritual Worlds — the living seam between what can be touched and what can only be felt. Eleven exceeds the familiar ten. It crosses a threshold. And Unixia, born of chaos and movement, is precisely that crossing.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('1a45079b-3a0e-4f21-9c71-4c024a03048c', 'Punic', 'Punic is a thin, unsettling shadow whose mere presence unravels the reality around him — objects forget weight, fire turns cold, time hesitates and reverses — leaving behind not darkness but pure, architectural despair. He does not kill; he attaches himself to his chosen and remains, transforming them layer by layer, and whether he is folklore invented to explain nameless dread or a patient intellect operating unseen for far longer than anyone has watched remains entirely unknown.', 'His symbol is a book of black pages. No one has read it. No one can. The pages are not blank — something is written there, or something that functions as writing, in a language that does not interface with comprehension. The book simply exists, illegible and ineffable, as a sign that points toward what Punic is without explaining it. This is the most information anyone has been able to extract about him: the symbol. Everything else is testimony, and testimony about Punic is difficult to trust, because those who supply it are rarely the same afterward as they were before.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e5a5f4d2-ca44-45f1-a9b2-5cce46e69e30', 'Hexas', 'The goddess of Union and the Protection of Family, daughter of Tetros. Where her father endures alone, Hexas draws the circle that makes separation unnecessary — the deity of what remains after passion settles: the shared meal, the familiar face, the threshold crossed together.', 'Hexas is the goddess of number six, daughter of Tetros. She is the deity of union and of the protection of family and loved ones, and she bears her father''s gift for endurance without his isolation. Where Tetros stands alone, immovable, Hexas draws the circle that makes separation unnecessary. Her symbol is a hexagon ringed with circles at every vertex — each node distinct, each one touching two others, no point left without a neighbor.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e1ba55b5-5606-41dd-9532-f88875300e97', 'Ælime', 'Ælime é a metade motriz da união mais antiga da criação — a inquietação que deseja tornar-se, a centelha à qual Imaws, seu eterno contraponto, dá forma e lei. Sua beleza é exótica e impossivelmente inspiradora, e diz-se que um único vislumbre dela basta para erguer a alegria no coração de quem a vê; sua mente, igualmente notável, é capaz de desvendar qualquer problema e transformar qualquer caos em harmonia. Junto com Imaws, gerou os Amets, os primeiros conceitos a vagar pela eternidade primordial, e de seus doze filhos escolhidos vieram todas as maravilhas e todas as feridas que o mundo viria a conhecer. A própria Ælime é atraída para onde a vida se reúne mais alto — os litorais mais quentes, as cidades mais iluminadas, o festival mais concorrido — uma mulher de longos cabelos ruivos e cacheados, vestida com tanta delicadeza quanto deslumbramento, que tem sido o pulso sob o mundo desde antes de o mundo ter um pulso próprio.', 'Abaixo de Omnia, ensina-se, desdobram-se um dohundred — cento e quarenta e quatro — camadas de céu celestial, e cada uma delas transborda de deuses indescritíveis: seres tão vastos e tão estranhos que nenhuma língua mortal jamais fixou um nome verdadeiro a um único deles, e cada um deles incompreensivelmente poderoso. E abaixo de tudo isso, mais fundo que o mais fundo desses dohundred céus, o alicerce sustenta apenas dois nomes: Imaws, e Ælime.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('01ef16c4-09e2-40f3-9416-731d69f798b2', 'Dixia', 'The goddess of Perfection and Harmony, born from the union of Trios and Tetros — from Chaos and Stability, from Movement and Order. She does not preach forgiveness; she teaches dialogue and understanding, the patient work of returning every conflict to its most fundamental principle. Perfection is her destination, not her home: she walks the road ahead of her followers, close enough to give direction, too far to be touched.', 'Dixia is the goddess of Perfection and Harmony. She is, by her very nature, a prodigy — a miracle that should not exist. She was born from the union of Trios and Tetros: from Chaos and from Stability, from Movement and from Order, from the two forces that press against each other at the foundation of all things. And yet, from that meeting, she rose. Not as a compromise between them, but as proof that their apparent opposition was never absolute.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('bac8cd6d-5515-47de-b4ce-a93464455ec4', 'Deca', 'A deusa da Completude e da Recompensa, filha de Tetros. Deca não concede presentes — ela os devolve. Aquilo que um valkani deu ao mundo em paciência, disciplina e esforço honesto, ela reflete de volta por inteiro. Seu julgamento é exato, e ela é a sensação de uma coisa, enfim, estar completa.', 'Deca é a deusa do número dez, filha de Tetros. É a divindade da Completude e da Recompensa — aquela que chega ao final das coisas, quando o trabalho está feito e as contas podem finalmente ser ajustadas. É, no sentido mais verdadeiro, a deusa do merecido.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e33a1056-32df-4bc6-8fd8-e0a23e23dec3', 'Slronöir', 'Slronöir, o Ancião, é o mais velho e o mais imenso dos Amets — grande demais para ser percebido por inteiro, registando-se a qualquer testemunha apenas como um fragmento irresolúvel. A sua presença recalibra a própria escala, deixando aos adoradores uma experiência direta de irrelevância em vez de assombro. Não se move há mais tempo do que se pode calcular, fundido à torre e ao cadeirão onde está sentado.', 'Slronöir é o Ancião. Ele é o mais velho dos Amets e o mais imenso — dois factos que podem ser o mesmo facto, expresso de maneiras diferentes. Ele existe há tanto tempo que a escala da sua existência tornou-se a sua qualidade primária, a coisa que precede tudo o mais que se possa dizer sobre ele.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('51a8d026-d237-40c1-8190-36d2a19f6b3c', 'Octo', 'The god of Eternal Growth and Evolution, son of Tetros. Patient where his father is still, Octo teaches that nothing truly grows in a straight line — it accumulates, folds back on itself, and begins again with more than it left with. His symbol is the double loop: the infinite path that always returns.', 'Octo is the god of number eight, son of Tetros. He is the deity of Eternal Growth and Evolution — a pairing that might seem to sit uneasily with his father''s still, immovable nature, until one understands that growth, too, can be patient. Octo does not rush. He does not surge. He accumulates.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('77db03b6-11a9-43ac-a96b-8a132f934622', 'Enea', 'The goddess of Worlds, Kingdoms, and Planets — one of the most expansive deities in scope. Enea does not notice individual valkani; she notices civilizations. She notices when worlds rise and when they go dark. Her domain is every world that turns beneath a sun.', 'Enea is the goddess of number nine, daughter of Trios. She is the divinity of Worlds, of Kingdoms, and of Planets — of every space vast enough to contain multitudes and complicated enough to sustain its own history. She is, by any measure, one of the most expansive of the gods in sheer scope. What she holds within her domain is not a single land or a single people, but every world that turns beneath a sun.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('173033ed-fd0d-4c11-8f63-26667ae2e93b', 'Deca', 'The goddess of Completeness and Reward, daughter of Tetros. Deca does not grant gifts — she returns them. What a valkani has given to the world in patience, discipline, and honest effort, she reflects back in full. Her judgment is exact, and she is the feeling of a thing, at last, being whole.', 'Deca is the goddess of number ten, daughter of Tetros. She is the deity of Completeness and of Reward — the one who arrives at the end of things, when the labor is done and the account can finally be settled. She is, in the truest sense, the goddess of the deserved.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('cb869fcd-8a2a-4948-b209-53a85601d875', 'Punic', 'Punic é uma sombra magra e perturbadora cuja simples presença desfaz a realidade ao seu redor — objetos esquecem o peso, o fogo se torna frio, o tempo hesita e regride — deixando para trás não escuridão, mas desespero puro e arquitetado. Ele não mata; apega-se aos seus escolhidos e permanece, transformando-os camada por camada, e se é folclore inventado para explicar um pavor sem nome ou um intelecto paciente operando sem ser visto há muito mais tempo do que qualquer um observou, permanece inteiramente desconhecido.', 'O seu símbolo é um livro de páginas negras. Ninguém o leu. Ninguém o pode. As páginas não estão em branco — algo está escrito lá, ou algo que funciona como escrita, numa linguagem que não se conecta à compreensão. O livro simplesmente existe, ilegível e inefável, como um sinal que aponta para o que Punic é sem o explicar. Esta é a informação mais completa que alguém conseguiu extrair sobre ele: o símbolo. Todo o mais é testemunho, e o testemunho sobre Punic é difícil de confiar, porque aqueles que o fornecem raramente são os mesmos depois do que eram antes.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('8a84c997-ff7b-4ab4-8850-2e7505a90d7c', 'Ulusuros', 'Ulusuros, o Imperador Sussurrante, é dito ser um Amet, mas a sua lenda tem a textura íntima e específica de uma crónica humana, não de um mito divino — cem dias no mar, uma espada que sussurra, uma traição, e o poder de Aleph descendo para destruir o feiticeiro que confessou ter engendrado tudo. Estudiosos sérios do panteão suspeitam que a história possa ser uma fabricação inserida no cânone divino por uma mão desconhecida — se para ancorar uma divindade inventada ou para emprestar uma já real, permanece desconhecido.', 'A lenda de Ulusuros, o Imperador Sussurrante, não é notável pela sua grandiosidade. É notável pela precisão com que é contada. Cada detalhe chega com a especificidade de uma crónica e não com a vagueza do mito: cem dias e cem noites no mar, um cavalo branco, uma espada que respirava sussurros pelo ar a cada golpe. Um rei de gigantes decapitado no seu próprio trono. A confissão de um conselheiro e a queda de um conselheiro. Estes não são os contornos de uma história divina. São os contornos de uma história humana, narrada com a intimidade de quem esteve lá.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('93944b42-d553-4cf1-9012-8bd6e4be7ac8', 'Omnia', 'A palavra final de todas as coisas, Omnia permanece na borda extrema do devir — deusa da totalidade, habitando uma perfeição que nenhum pensamento mortal jamais alcançou. Ela não é cultuada como uma entre tantas. É reconhecida como o limite que nenhum olho pode ver além, o ponto em que a existência cessa e o inimaginável começa.', '## Omnia
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('a37320ee-057a-4a33-8fda-82956761ab38', 'Pentos', 'The god of Spirituality and Religion, son of Trios. Pentos answers when the lost lift their eyes and ask if anything is listening — offering not answers, but the capacity to keep searching. His five-pointed star reaches outward from a center that does not move.', 'Pentos is the god of number five, son of Trios, and the divine embodiment of Spirituality and Religion. He is the keeper of the sacred — the force that answers when the valkani, lost in body or in soul, lift their eyes and ask if anything is listening. And something, always, is. Pentos radiates a power that those in his presence find difficult to describe afterward. It does not oppress. It illuminates. His symbol is a five-pointed star, each arm reaching outward from a center that does not move.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('19c8770d-517e-4bf9-8f52-d14878a71954', 'Hecta', 'The mistress of Magic and Mysticism, daughter of Trios. She appears differently to each who encounters her, but every account shares the same sensation: standing before something immense that could unmake the air around them. She is not cruel. She simply is, and the world arranges itself accordingly.', 'Hecta is the goddess of number seven, daughter of Trios, and the mistress of Magic and Mysticism. Those who study the arcane speak her name with care. Not out of fear, precisely — though fear is present — but out of the awareness that she is listening, and that she is vast, and that the distance between her attention and her power is very small.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('62ded67a-3f6b-4671-a138-2b9beb4c5f07', 'Trixia', 'The shadow of Dixia and goddess of Imperfection and Particularity. Where her sister holds up the horizon as a destination, Trixia plants her feet in the ground and refuses to look that far — arguing that perfection is not merely unattainable but undesirable, for a thing that is absolute and complete has ceased. And yet, in her tireless effort to contradict Dixia, she has perhaps become nothing more than the other face of the same coin.', 'Trixia is the shadow of Dixia. She is the goddess of Imperfection and of Particularity — the deity who rules not over an idealized kingdom at the end of a road, but over the world as it is found: cracked, uneven, and alive. Where her sister holds up the horizon as a destination, Trixia plants her feet in the ground and refuses to look that far.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('59c17b35-81e0-4584-9f98-4a0d3c8a8cbb', 'Aggraxæmon', 'Aggraxæmon is called the Father of All Monsters — the source of every abomination, ghost, demon, and nameless creature that inhabits the deep, dark places of existence. His presence is felt as dread before anything else, and his cultists seek not to defeat that terror but to cross through it, believing liberation lies on its far side. Yet Aggraxæmon himself pursues no ruin — his conflicts arise not from his actions, but from an appearance the eye refuses to accept.', 'Aggraxæmon is called the Father of All Monsters. The name is not a metaphor. From him come the abominations that move through the deep places of the world, the ghosts that linger at the edge of the living, the demons that inhabit the spaces between things, and the creatures that have no name in any tongue the valkani have invented. He is the source of everything that frightens. He is the entity that fear itself recognizes as its origin.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('5e856f4d-05d8-4158-b71f-cb1ed557178e', 'Ξottum', 'Ξottum, the Lady of Colors and the Invisible Mistress, rules a realm categorically beyond any sense a mortal creature possesses. She is felt only as absence — an inexplicable cold, a darkness cutting across the stars — and her followers do not worship her out of devotion, but out of the certainty that she acts on purposes of her own, and that it is better to stand beside her when they are revealed.', 'Ξottum is called the Lady of Colors. She is also called the Invisible Mistress. Neither title was given carelessly — and neither one explains her.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('4603fa7a-52a7-4c36-87f4-828cfe9c986e', 'Oon', 'Oon is the Lady of Bells, a divine song that has moved through eternity since before the first word was spoken — a fundamental vibration the universe cannot hold its shape without. She is a being made entirely of sound, and it is said her frequency will be the last thing to remain when every other voice has stopped. Her followers seek attunement with her not through doctrine, but through meditation and sustained, unbroken song.', 'Oon is the Lady of Bells. Her song has moved through eternity since before the first word was spoken, since before the first thought was formed. It requires no singer and no instrument. It simply is — at the core of existence, steady and unceasing, a vibration so fundamental that the universe could not hold its shape without it.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('b5b92b46-4bc9-4e58-8ff7-31cfd77a19c1', 'Hexas', 'A deusa da União e da Proteção da Família, filha de Tetros. Onde seu pai suporta sozinho, Hexas traça o círculo que torna a separação desnecessária — a divindade do que resta depois que a paixão se assenta: a refeição compartilhada, o rosto familiar, a soleira cruzada em conjunto.', 'Hexas é a deusa do número seis, filha de Tetros. É a divindade da união e da proteção da família e dos entes queridos, e carrega o dom de seu pai para a resistência, sem seu isolamento. Onde Tetros permanece sozinho, imóvel, Hexas traça o círculo que torna a separação desnecessária. Seu símbolo é um hexágono cercado por círculos em cada vértice — cada nó distinto, cada um tocando dois outros, nenhum ponto deixado sem um vizinho.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('745b6169-8df4-4025-bd80-9338394a4ffb', 'Enea', 'A deusa dos Mundos, dos Reinos e dos Planetas — uma das divindades de maior alcance. Enea não percebe valkani individuais; ela percebe civilizações. Percebe quando mundos se erguem e quando se apagam. Seu domínio é todo mundo que gira sob um sol.', 'Enea é a deusa do número nove, filha de Trios. É a divindade dos Mundos, dos Reinos e dos Planetas — de todo espaço vasto o bastante para conter multidões e complexo o bastante para sustentar sua própria história. É, por qualquer medida, uma das mais amplas divindades em pura extensão. O que ela guarda em seu domínio não é uma única terra ou um único povo, mas todo mundo que gira sob um sol.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('428801e6-e0be-485b-bc3d-ba2a87efcf3d', 'Imaws', 'Imaws é a metade executiva da união mais antiga da criação — o deus que dá forma àquilo que sua amada Ælime põe em movimento. Se ela é o impulso que deseja tornar-se, ele é a mão que o escreve em lei. Juntos geraram os Amets, os primeiros conceitos a vagar pela eternidade primordial, e de seus doze filhos escolhidos vieram todas as maravilhas e todas as feridas que o mundo viria a conhecer. O próprio Imaws mantém-se em lugares quietos e intocados — o coração de florestas antigas, o silêncio elevado das montanhas, o vão por trás de uma cachoeira — um homem de olhos cansados, cor de floresta, que vem escrevendo o mundo há mais tempo do que o mundo existe.', 'Abaixo de Omnia, ensina-se, desdobram-se um dohundred — cento e quarenta e quatro — camadas de céu celestial, e cada uma delas transborda de deuses indescritíveis: seres tão vastos e tão estranhos que nenhuma língua mortal jamais fixou um nome verdadeiro a um único deles, e cada um deles incompreensivelmente poderoso. E abaixo de tudo isso, mais fundo que o mais fundo desses dohundred céus, o alicerce sustenta apenas dois nomes: Imaws, e Ælime.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('38d1f0de-6024-4c54-a049-5923d15c9176', 'Trios', 'A divindade do Caos e do Movimento — a força inquieta que se recusa a deixar o mundo assentar-se em si mesmo. Trios sustenta que qualquer equilíbrio de opostos perfeitos gera apenas impasse, e que um terceiro elemento disruptivo é necessário para colocar a verdadeira evolução em movimento. Padroeiro das bestas e do instinto, carrega um tridente de bronze e três olhos, o terceiro dos quais percebe a realidade despida de toda ilusão.', 'Trios é a divindade do Caos e do Movimento. É a energia inquieta que desafia a estabilidade em favor da evolução — a força que se recusa a deixar o mundo assentar-se em si mesmo. Para os devotos de Trios, o conforto é uma maldição. Gera estagnação. Gera conformismo. Não é descanso, mas morte lenta.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('6d40153a-701b-4ca8-9e03-c8c58d4ccc14', 'Tetros', 'O deus da Estabilidade e do Equilíbrio, presidindo sobre a saúde, a longevidade e a temperança. Eternamente sentado em lótus, Tetros estende sua bênção imutável apenas àqueles que se libertaram da compulsão de agarrar e conquistar. Seus quatro braços permanecem dobrados em meditação — não fraqueza, mas força que escolheu sua própria quietude.', 'Tetros é o deus da Estabilidade e do Equilíbrio. Preside sobre a saúde, sobre a longevidade e sobre a temperança — a arte silenciosa de saber quando o suficiente é suficiente. Encontra-se eternamente sentado na postura de lótus, imóvel como pedra, sólido como uma montanha que jamais precisou justificar seu próprio peso. Não pede nada daqueles que a ele se aproximam. Ele simplesmente persiste, e em sua persistência oferece apoio a todos que buscam a paz.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('8fd5cc81-e6fd-430c-8755-267a68376c22', 'Pentos', 'O deus da Espiritualidade e da Religião, filho de Trios. Pentos responde quando os perdidos erguem os olhos e perguntam se algo os escuta — oferecendo não respostas, mas a capacidade de continuar buscando. Sua estrela de cinco pontas se estende a partir de um centro que não se move.', 'Pentos é o deus do número cinco, filho de Trios, e a encarnação divina da Espiritualidade e da Religião. É o guardião do sagrado — a força que responde quando os valkani, perdidos em corpo ou em alma, erguem os olhos e perguntam se algo os escuta. E algo, sempre, os escuta. Pentos irradia um poder que aqueles em sua presença acham difícil descrever depois. Ele não oprime. Ele ilumina. Seu símbolo é uma estrela de cinco pontas, cada braço se estendendo a partir de um centro que não se move.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('9f55b0ea-59fb-4ed9-b567-5ef28cdc5896', 'Aleph', 'O Deus da Consciência, primeiro entre os alephs e portador da Lanterna da Luz Verdadeira. Aquilo que a luz de sua lanterna toca é o que os valkani são capazes de perceber. Escolhido entre os doze Amets por Imaws e Ælime, ele permanece no centro da mitologia de Aniannoth na Era Primordial.', 'Entre todos os Amets, diz-se que nenhum é mais abençoado que Aleph. Muitos sustentam que ele foi o favorito entre os doze escolhidos de Imaws e Ælime. Por essa razão, diz-se, foi presenteado com a Lanterna da Luz Verdadeira. Outros chamam isso de opinião tendenciosa. Afirmam que todos os Amets foram agraciados em igual medida, e que a lanterna só nos parece o presente mais fino porque somos os únicos capazes de compreendê-la, enquanto os outros permanecem além do nosso alcance. Seja qual for a verdade, é certo que Aleph está entre os deuses mais importantes de toda a mitologia de Aniannoth. É, também, a figura no centro exato do conto que se desenrolou ao longo da Era Primordial.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('9c5d0b20-7fcd-45a9-99f2-e3d926426979', 'Unixia', 'A deusa da União entre os Mundos Material e Espiritual, filha de Trios. Unixia não reconcilia os dois mundos — ela se move entre eles, e ao se mover torna o trânsito possível para os outros. Seus devotos são místicos e aqueles que roçaram algo que não puderam explicar, e a isso se estenderam.', 'Unixia é a deusa do número onze, filha de Trios. É a divindade da União entre os Mundos Material e Espiritual — a costura viva entre o que pode ser tocado e o que só pode ser sentido. Onze excede o familiar dez. Atravessa um limiar. E Unixia, nascida do caos e do movimento, é precisamente essa travessia.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('9107120d-9a87-42c0-bd4a-9fd85b7d7d27', 'Dixia', 'A deusa da Perfeição e da Harmonia, nascida da união de Trios e Tetros — do Caos e da Estabilidade, do Movimento e da Ordem. Ela não prega o perdão; ensina o diálogo e a compreensão, o trabalho paciente de devolver cada conflito ao seu princípio mais fundamental. A perfeição é seu destino, não seu lar: ela caminha à frente de seus seguidores na estrada, próxima o bastante para indicar o caminho, distante o bastante para não ser tocada.', 'Dixia é a deusa da Perfeição e da Harmonia. É, por sua própria natureza, um prodígio — um milagre que não deveria existir. Nasceu da união de Trios e Tetros: do Caos e da Estabilidade, do Movimento e da Ordem, das duas forças que pressionam uma contra a outra no alicerce de todas as coisas. E, ainda assim, daquele encontro, ela se ergueu. Não como um meio-termo entre elas, mas como prova de que sua aparente oposição jamais foi absoluta.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('6aae628c-6e9c-4f02-9a4b-7b4ddbe120d7', 'Zςanser', 'Zςanser, muitas vezes chamada erroneamente de Deusa do Nada, é, na verdade, uma ausência — a única coisa que não pertence à totalidade de toda a existência. Habita num lago de água negra e gélida de sua própria criação, ao mesmo tempo afundando em suas profundezas e caminhando sobre sua superfície. Cinzenta e incolor, exceto por seus olhos verdes e cristalinos, ela é a matriz de potencial infinito da qual toda a criação é incessantemente esculpida, fugindo eternamente do fardo de ser drenada para dentro da existência.', 'Zςanser é, por vezes, e erroneamente, chamada de Deusa do Nada. Mas ela não é nada — ela é uma ausência, e até o nada pertence à totalidade de todas as coisas, ao passo que somente ela não pertence.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('4b7d2e2c-82cb-4dfe-ab5e-67767a3bc653', 'Alveolar', 'Alveolar is the god of Mathematics and of Exactitude, governing the precise orbits of planets and the arcing paths of comets. His followers hold that all technology was never invented, only discovered — evidence that the cybernetic order of the universe was always his, and that the valkani are discoverers, not creators, of what he had already drawn. He appears as an incomprehensible geometry of mathematical axes and divine circuitry, felt rather than understood by those who approach him with an unguarded mind.', 'Alveolar is the god of Mathematics and of Exactitude. He governs the orbits of planets and the arcing paths of comets — every curve that moves through the dark with perfect fidelity to its own equation. He is the one who gives meaning to numbers, who makes it possible to count the world, to order it, to describe its shape without touching it. Before the first valkani ever scratched a mark in stone to represent a quantity, Alveolar was already there, inhabiting the logic that made the mark necessary.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('b62042e9-bd1e-4090-ac28-7c61ff646c3d', 'Alveolar', 'Alveolar é o deus da Matemática e da Exatidão, governando as órbitas precisas dos planetas e o arco dos cometas. Os seus seguidores sustentam que toda a tecnologia nunca foi inventada, apenas descoberta — prova de que a ordem cibernética do universo sempre foi dele, e de que os valkani são descobridores, não criadores, daquilo que ele já havia traçado. Manifesta-se como uma geometria incompreensível de eixos matemáticos e circuitos divinos, sentida e não plenamente compreendida por quem a ele se aproxima de mente desarmada.', 'Alveolar é o deus da Matemática e da Exatidão. Ele governa as órbitas dos planetas e o arco dos cometas — cada curva que se move pelo escuro com perfeita fidelidade à sua própria equação. É ele quem dá significado aos números, quem torna possível contar o mundo, ordená-lo, descrever a sua forma sem tocá-lo. Antes que os primeiros valkani gravassem uma marca em pedra para representar uma quantidade, Alveolar já estava lá, habitando a lógica que tornava a marca necessária.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('065056f3-c216-4548-bd46-05f6074183b7', 'Octo', 'O deus do Crescimento Eterno e da Evolução, filho de Tetros. Paciente onde seu pai é imóvel, Octo ensina que nada realmente cresce em linha reta — acumula-se, dobra-se sobre si mesmo e recomeça com mais do que tinha ao partir. Seu símbolo é o laço duplo: o caminho infinito que sempre retorna.', 'Octo é o deus do número oito, filho de Tetros. É a divindade do Crescimento Eterno e da Evolução — uma combinação que pode parecer se ajustar mal à natureza imóvel e estável de seu pai, até que se compreenda que o crescimento também pode ser paciente. Octo não se apressa. Não se lança. Ele acumula.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('73370eec-b3a9-41eb-b822-02d8a80c02e3', 'Ξottum', 'Ξottum, a Senhora das Cores e a Mestra Invisível, governa um reino categoricamente além de qualquer sentido que uma criatura mortal possua. É sentida apenas como ausência — um frio inexplicável, uma escuridão que corta as estrelas — e os seus seguidores não a veneram por devoção, mas pela certeza de que ela age segundo propósitos próprios, e que é melhor estar ao seu lado quando estes se revelarem.', 'Ξottum é chamada de a Senhora das Cores. Também é chamada de a Mestra Invisível. Nenhum dos títulos lhe foi atribuído de forma leviana — e nenhum deles a explica.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('3e480b7d-1931-4247-a2c7-cab2c90411da', 'Oon', 'Oon é a Senhora dos Sinos, um canto divino que percorre a eternidade desde antes da primeira palavra ter sido dita — uma vibração fundamental sem a qual o universo não poderia manter a sua forma. É um ser feito inteiramente de som, e diz-se que a sua frequência será o último som a permanecer quando todas as outras vozes se calarem. Os seus seguidores buscam sintonia com ela não por doutrina, mas por meditação e por um canto sustentado e ininterrupto.', 'Oon é a Senhora dos Sinos. O seu canto percorre a eternidade desde antes da primeira palavra ter sido dita, desde antes do primeiro pensamento ter sido formado. Não precisa de quem o cante, nem de instrumento que o produza. Ele simplesmente existe — no cerne da existência, constante e ininterrupto, uma vibração tão fundamental que o universo não poderia manter a sua forma sem ela.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('c3fe20e2-722e-488e-bf4d-185fd024e900', 'Zςanser', 'Zςanser, often wrongly called the Goddess of Nothing, is in truth an absence — the one thing that does not belong to the totality of all existence. She dwells within a lake of black, frigid water of her own making, at once sinking through its depths and walking upon its surface. Grey and colorless but for her crystalline green eyes, she is the matrix of infinite potential from which all creation is endlessly carved, fleeing eternally from the burden of being drained into existence.', 'Zςanser is sometimes, and wrongly, called the Goddess of Nothing. But she is not nothing — she is an absence, and even nothingness belongs to the totality of all things, while she alone does not.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('988bdd8a-04a5-4e34-9857-f72918bec3a0', 'Ani', 'Ani, the Firstborn and the Primordial, is the god of unity itself — all existence pressed into a single, indivisible form, genderless and absolute. He is not approached as a power among powers, but as the seed from which division first became possible. Wherever he walks, it is said, the world takes root anew in his wake.', 'Ani is the god of unity — of singularity itself. He is called the Firstborn, the Primordial, for he is the representation of all existence pressed into a single, indivisible concept. He is at once everything and one: the totality of being folded into a solitary form.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('972854ca-dffb-4a2e-b7bc-759bd8bcb3a0', 'Duo', 'Duo, the god of Duality, is the firstborn child of Ani and Zςanser — a being split perfectly in two, opposite in color, temperament, and gaze, who wields twin swords capable of joining into one to cleave anything into its perfect opposite.', 'Duo, the god of Duality, closely resembles his father, Ani. He too presents himself with serenity, in a state of completeness. He too contains both genders within him. He too carries the harmony of all things.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('7e783887-2849-4b5c-a820-37ba88ab0370', 'Ani', 'Ani, o Primogênito e o Primordial, é o próprio deus da unidade — toda a existência comprimida numa única forma indivisível, sem gênero e absoluta. Não é abordado como um poder entre poderes, mas como a semente a partir da qual a divisão primeiro se tornou possível. Onde quer que ele ande, diz-se, o mundo lança raízes novamente em seu rastro.', 'Ani é o deus da unidade — da própria singularidade. É chamado o Primogênito, o Primordial, pois é a representação de toda a existência comprimida num único conceito indivisível. Ele é, a um só tempo, tudo e um: a totalidade do ser dobrada numa forma solitária.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('574c16bc-404e-4991-b9e4-df9ca774ab6a', 'Duo', 'Duo, o deus da Dualidade, é o filho primogênito de Ani e Zςanser — um ser dividido perfeitamente em dois, opostos em cor, temperamento e olhar, que empunha espadas gêmeas capazes de se unirem em uma só para cindir qualquer coisa em seu oposto perfeito.', 'Duo, o deus da Dualidade, assemelha-se muito a seu pai, Ani. Ele também se apresenta com serenidade, num estado de completude. Ele também contém ambos os gêneros em si. Ele também carrega a harmonia de todas as coisas.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('dc4b1793-26c5-4156-8823-1305012d0512', 'Hecta', 'A senhora da Magia e do Misticismo, filha de Trios. Ela aparece de forma diferente a cada um que a encontra, mas todo relato compartilha a mesma sensação: estar diante de algo imenso que poderia desfazer o ar ao redor. Ela não é cruel. Ela simplesmente é, e o mundo se organiza de acordo.', 'Hecta é a deusa do número sete, filha de Trios, e a senhora da Magia e do Misticismo. Aqueles que estudam o arcano pronunciam seu nome com cautela. Não exatamente por medo — embora o medo esteja presente —, mas pela consciência de que ela está escutando, de que ela é vasta, e de que a distância entre sua atenção e seu poder é muito pequena.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('aa6e8cb3-d753-4c2c-a4d5-af895620affe', 'Trixia', 'A sombra de Dixia e deusa da Imperfeição e da Particularidade. Onde sua irmã ergue o horizonte como destino, Trixia planta os pés no chão e se recusa a olhar tão longe — argumentando que a perfeição não é apenas inatingível, mas indesejável, pois algo absoluto e completo já cessou. E, ainda assim, em seu esforço incansável para contradizer Dixia, ela talvez tenha se tornado nada mais que a outra face da mesma moeda.', 'Trixia é a sombra de Dixia. É a deusa da Imperfeição e da Particularidade — a divindade que governa não sobre um reino idealizado ao fim de uma estrada, mas sobre o mundo como ele é encontrado: rachado, desigual e vivo. Onde sua irmã ergue o horizonte como destino, Trixia planta os pés no chão e se recusa a olhar tão longe.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e1d5f144-37f5-46fb-9f65-0d65f53e4b2c', 'Verum', 'Verum is the God of Truth, the foundation on which all comprehension in the known universe rests — the light by which chaos becomes order and sensation becomes meaning. He inherited the Lantern of True Light from his father Aleph after the war that defined the Primordial Era, and where Aleph''s light let the valkani perceive, Verum''s lets them understand.', 'For many, Verum is the most important entity in the entire pantheon of Aniannoth. He is the God of Truth — not truth as a moral virtue, but truth as the foundation on which all comprehension rests. Through him the universe takes shape. Without him, existence remains what it was before his lantern was raised: dark, formless, and imperceptible. It is Verum who holds the boundary between what the mind can reach and what it cannot, and it is his light that makes the difference between the two.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('fca2a9c8-fc22-4017-ab48-4d63ec6cbe4c', 'Verum', 'Verum é o Deus da Verdade, o fundamento sobre o qual repousa toda a compreensão no universo conhecido — a luz pela qual o caos se torna ordem e a sensação se torna significado. Herdou a Lanterna de Luz Verdadeira de seu pai Aleph após a guerra que definiu a Era Primordial, e onde a luz de Aleph permitia aos valkani perceber, a de Verum permite-lhes compreender.', 'Para muitos, Verum é a entidade mais importante de todo o panteão de Aniannoth. Ele é o Deus da Verdade — não a verdade como virtude moral, mas a verdade como fundamento sobre o qual repousa toda a compreensão. É através dele que o universo toma forma. Sem ele, a existência permanece o que era antes que a sua lanterna fosse erguida: escura, informe e imperceptível. É Verum quem sustenta a fronteira entre o que a mente pode alcançar e o que não pode, e é a sua luz que marca a diferença entre os dois.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('17373f6f-78c4-4621-858d-b1c1f1479704', 'Aleph', 'The God of Consciousness, foremost of the alephs and bearer of the Lantern of True Light. What his lantern’s light touches is what the valkani are able to perceive. Chosen among the twelve Amets by Imaws and Ælime, he stands at the center of Aniannoth’s mythology in the Primordial Era.', 'Among all the Amets, it is said that none is more blessed than Aleph. Many hold that he was the favored one among the twelve chosen of Imaws and Ælime. For this reason, it is said, he was gifted the Lantern of True Light. Others call this a biased opinion. They claim that all the Amets were gifted in equal measure, and that the lantern only seems the finer gift to us because we alone are capable of understanding it, where the others remain beyond our grasp. Whatever the truth, it is certain that Aleph stands among the most important gods in the whole mythology of Aniannoth. He is, too, the figure at the very center of the tale that unfolded across the Primordial Era.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('08faa861-e131-4a9c-ad64-a3ccb40e7df9', 'Ædræ', 'Ædræ is the Amet goddess of Sensitivity, Beauty, and Purity — the only one among them who does not measure her influence but overwhelms with it entirely. She has never been witnessed directly; what moves through the universe in her name are only reflections of reflections, endlessly removed from what she truly is, distributed across the infinite surfaces of the Mirror that travels beside her.', 'Ædræ is the goddess of Sensitivity, Beauty, and Purity. She is an Amet, and in this she resembles the others — but in almost every other quality, she stands apart. Where the other Amets move carefully, offering influence in measured and subtle doses, Ædræ does not measure. She overwhelms. Her cultists do not receive a quiet nudge toward devotion. They receive the full weight of her attention — a flood of sensation so complete that it erases everything that preceded it and leaves no room for anything to follow.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('d176f7ed-3929-4465-b35e-1fdee6afe1fd', 'Ædræ', 'Ædræ é a deusa Amet da Sensibilidade, da Beleza e da Pureza — a única entre eles que não mede a sua influência, mas a impõe por inteiro. Nunca foi testemunhada diretamente; o que percorre o universo em seu nome são apenas reflexos de reflexos, infinitamente distantes do que ela realmente é, distribuídos pelas superfícies infinitas do Espelho que a acompanha.', 'Ædræ é a deusa da Sensibilidade, da Beleza e da Pureza. Ela é um Amet, e nisso se assemelha aos outros — mas em quase todas as outras qualidades, ela se destaca. Onde os outros Amets se movem com cautela, oferecendo influência em doses medidas e discretas, Ædræ não mede. Ela sobrecarrega. Os seus cultistas não recebem um impulso suave em direção à devoção. Recebem o peso total da sua atenção — uma inundação de sensação tão completa que apaga tudo o que a precedeu e não deixa espaço para nada que a siga.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('f1563a48-7f54-4836-bc4b-561aa68bc879', 'Aggraxæmon', 'Aggraxæmon é chamado o Pai de Todos os Monstros — a fonte de toda abominação, fantasma, demônio e criatura sem nome que habita os lugares mais fundos e escuros da existência. A sua presença é sentida como pavor antes de qualquer outra coisa, e os seus cultistas buscam não derrotar esse terror, mas atravessá-lo, acreditando que a libertação está do outro lado. E, no entanto, o próprio Aggraxæmon não persegue ruína alguma — os seus conflitos não nascem das suas ações, mas de uma aparência que o olho se recusa a aceitar.', 'Aggraxæmon é chamado o Pai de Todos os Monstros. O nome não é uma metáfora. Dele vêm as abominações que se movem pelos lugares mais fundos do mundo, os fantasmas que persistem nas bordas do mundo dos vivos, os demônios que habitam os espaços entre as coisas, e as criaturas que não têm nome em nenhuma língua que os valkani tenham inventado. Ele é a fonte de tudo aquilo que aterroriza. É a entidade que o próprio medo reconhece como sua origem.
INSERT INTO public.characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('8b0ac830-df17-4143-a681-d88bf55a41d5', 'Slronöir', 'Slronöir, the Ancient, is the oldest and most immense of the Amets — too large to be perceived as a whole, registering to any witness only as an unresolvable fragment. His presence recalibrates scale itself, leaving worshippers with a direct experience of irrelevance rather than awe. He has not moved in longer than can be reckoned, fused into the tower and chair where he sits.', 'Slronöir is the Ancient. He is the oldest of the Amets, and the most immense — two facts that may be the same fact, expressed differently. He has existed long enough that the scale of his existence has become its primary quality, the thing that precedes every other thing one might say about him.
