INSERT INTO public.factions (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('c964a915-17e2-4bb6-949e-50b2cfdc20d1', 'The Numeric Gods', 'The Numeric Gods are the primordial deities born from Alveolar''s lineage, each embodying a number from zero to thirteen and the fundamental force it represents — from Zςanser''s absolute void to Trixia''s revolution. Ranking below the Amets in the hierarchy of power, they are the architecture beneath the architecture of existence itself.', 'Before the Numeric Gods existed, there was a number. And before the number, there was Alveolar — the god of Mathematics and Exactitude, the Amet who gave meaning to quantity itself. From him, in one form or another, all of them descend. They are the living embodiment of the primordial forces that structure reality: not merely divine rulers of abstract domains, but the concepts themselves, made sovereign and given will.
INSERT INTO public.factions (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('186e1df4-226c-4a0c-b0ab-3520aad3f91f', 'Os Deuses Numéricos', 'Os Deuses Numéricos são as divindades primordiais nascidas da linhagem de Alveolar, cada uma encarnando um número de zero a treze e a força fundamental que ele representa — do vazio absoluto de Zςanser à revolução de Trixia. Situados abaixo dos Amets na hierarquia do poder, são a arquitetura debaixo da arquitetura da própria existência.', 'Antes de os Deuses Numéricos existirem, havia um número. E antes do número, havia Alveolar — o deus da Matemática e da Exatidão, o Amet que deu significado à quantidade em si. Dele, de uma forma ou de outra, todos eles descendem. São a encarnação viva das forças primordiais que estruturam a realidade: não apenas governantes divinos de domínios abstratos, mas os próprios conceitos, feitos soberanos e dotados de vontade.
INSERT INTO public.faction_categories (faction_id, category) VALUES ('c964a915-17e2-4bb6-949e-50b2cfdc20d1', 'DIVINE');
