INSERT INTO public.faction_members (faction_id, character_id, display_order) VALUES ('186e1df4-226c-4a0c-b0ab-3520aad3f91f', 'aa6e8cb3-d753-4c2c-a4d5-af895620affe', 13);
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('3f93f644-fa20-4e6f-88f2-366dc5f2bf47', 'The Lantern of True Light', 'The Lantern of True Light is the most sacred object in the known universe — first carried by Aleph, passed to his son Verum after the holy war of the Primordial Era. Its light creates a domain of knowability divided into three concentric sectors: the Illuminated, where truth and meaning hold firm; the Penumbra, home to glimpsed but unresolved concepts; and the Shadow, where thought cannot reach and unseen things move.', 'The Lantern of True Light is the most sacred object in the known universe. It was first carried by Aleph, who received it as a gift from Imaws and Ælime among the twelve Amets, and it passed to Verum after his victory over Z''Mthun in the holy war of the Primordial Era. What Aleph''s lantern illuminated, one could perceive. What Verum''s illuminates, one can also understand.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('69b9209e-359b-46e1-a472-f684d17694f9', 'A Lanterna de Luz Verdadeira', 'A Lanterna de Luz Verdadeira é o objeto mais sagrado do universo conhecido — carregada primeiro por Aleph, e passada ao seu filho Verum após a guerra sagrada da Era Primordial. A sua luz cria um domínio de cognoscibilidade dividido em três setores concêntricos: o Iluminado, onde a verdade e o significado se mantêm firmes; a Penumbra, lar de conceitos vislumbrados mas não resolvidos; e a Sombra, onde o pensamento não alcança e coisas invisíveis se movem.', 'A Lanterna de Luz Verdadeira é o objeto mais sagrado do universo conhecido. Foi carregada primeiro por Aleph, que a recebeu como presente de Imaws e Ælime entre os doze Amets, e passou para Verum após a sua vitória sobre Z''Mthun na guerra sagrada da Era Primordial. O que a lanterna de Aleph iluminava, podia-se perceber. O que a de Verum ilumina, pode-se também compreender.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('26c703b3-320e-4bbe-a7d6-41353b79f94c', 'O Espelho de Ædræ', 'O Espelho de Ædræ é o labirinto de reflexos que se multiplica sem fim, viajando ao lado da deusa Ædræ, refracionando a sua presença avassaladora em cópias demasiado diluídas para causar dano. Protege o universo dela diretamente — e, ao fazê-lo, confina-a dentro da sua própria geometria infinita, um labirinto que ela não escolheu e do qual nunca encontrou a borda.', 'O Espelho de Ædræ viaja ao seu lado. Não é um único objeto — ou é, e essa é a fonte do problema. Ele se multiplica sem limite, replicando-se infinitamente, imagem dentro de imagem dentro de imagem, produzindo um labirinto de reflexos cujas câmaras interiores contêm reflexos desses reflexos, e assim por diante, sem fim. Não foi feito para aprisioná-la. Foi feito para proteger tudo o mais.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('48266bba-4f4d-4ae2-9b0f-4b60f4c316d5', 'The Mirror of Ædræ', 'The Mirror of Ædræ is the endlessly multiplying labyrinth of reflections that travels beside the goddess Ædræ, refracting her overwhelming presence into copies too diffuse to cause harm. It protects the universe from her directly — and, in doing so, confines her within its own infinite geometry, a maze she did not choose and has never found the edge of.', 'The Mirror of Ædræ travels beside her. It is not a single object — or it is, and that is the source of the problem. It multiplies without limit, replicating itself endlessly, image within image within image, producing a labyrinth of reflections whose inner chambers contain reflections of those reflections, and so on without terminus. It was not made to imprison her. It was made to protect everything else.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('9f447692-3301-4b1a-8e1c-d6fc0fe16d1f', 'The Mask of Ulusuros', 'The Mask of Ulusuros is the unnervingly consistent expression of courage worn by the Whispering Emperor throughout his legend — too steady to be a genuine face caught mid-battle or mid-betrayal. Whatever it actually conceals has never been seen, and has not yet done what it came to do.', 'Those who study the legend closely note, eventually, the same thing: the courage on his face does not quite match the rest of the story. It is too consistent. It does not shift the way genuine emotion shifts across a face caught mid-battle or mid-betrayal. It holds.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('c7c9b0c5-d36e-45cf-99aa-4459fa311e32', 'A Máscara de Ulusuros', 'A Máscara de Ulusuros é a expressão de coragem inquietantemente consistente usada pelo Imperador Sussurrante ao longo da sua lenda — firme demais para ser um rosto genuíno apanhado a meio de uma batalha ou de uma traição. O que quer que ela na verdade oculte nunca foi visto, e ainda não fez o que veio fazer.', 'Aqueles que estudam a lenda com atenção notam, eventualmente, a mesma coisa: a coragem no seu rosto não corresponde inteiramente ao resto da história. É consistente demais. Não oscila da forma como a emoção genuína oscila num rosto apanhado a meio de uma batalha ou a meio de uma traição. Ela se mantém.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('c401dda6-742c-4424-a2a6-d22cec836e0d', 'The Crown of Aggraxæmon', 'The Crown of Aggraxæmon is not a symbol of authority but an engine — the continuous, uncapped process by which he emanates every abomination, demon, and nameless creature that moves through the dark, each one bound to him by the essence it was made from.', 'The Crown of Aggraxæmon does not sit on his head as a symbol of authority. It sits there as an engine. From it flows the continuous process by which Aggraxæmon produces life — not through union with another, not through choice made in a specific moment, but as an ongoing act of emanation, the way a fire produces heat and cannot stop producing it.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('b165ae36-0128-473a-af8b-cd281196925d', 'The Veil of Ξottum', 'The Veil of Ξottum lends its wearer Ξottum''s own nature of absence — not concealment, but the technical condition of not registering to any sense or instrument at all. To wear it is to become, briefly, part of the domain that already lies beyond perception.', 'The Veil of Ξottum was not made. It emerged from her, the way all things in her domain emerge — not produced, but present, without origin that can be traced. It is worn, when it is worn at all, without sensation. The bearer does not feel it settle over them. They simply cease to be findable.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('ca99a05c-3387-4b1f-b5fc-0b045d7a835a', 'The Lens of Alveolar', 'The Lens of Alveolar refracts comprehension rather than light — pointed at anything, it delivers a complete account of what it is and how it behaves, arriving whole and instantly, with a weight most bearers describe as the closest they have come to ceasing to be themselves.', 'The Lens of Alveolar is a circle of material that does not refract light in any ordinary sense. What it refracts is comprehension. Point it toward a thing — any thing, any system, any structure — and what arrives in the bearer''s understanding is not an image. It is a complete account: every dimension, every relationship, every number that describes what the thing is and how it behaves and what will happen to it, arriving simultaneously and fully formed, without the delay of study or the gaps of interpretation.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('b4d5fd91-efb4-4859-8319-98ed19dcc88f', 'The Bell of Oon', 'The Bell of Oon does not ring but resonates without end, generating energy from a source connected to Oon''s own vibration rather than drawing from any finite reserve — a resonance its bearers describe as confirming something that was always present beneath everything.', 'The Bell of Oon does not ring. It resonates — and the distinction is not trivial. A ring is an event. A resonance is a state. The Bell, once set in motion, does not produce a sound that rises and falls and ends. It produces a vibration that does not end, that does not diminish with distance, that does not require the medium through which sound normally travels. It operates at a frequency beneath what ears are made to process and above what matter is made to resist.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('53f1f1c5-f799-4b9d-9e24-5178df8865d0', 'The Chalice of Zςanser', 'The Chalice of Zςanser is never empty, filled always with the water of her black lake — to drink from it is to be subtracted from the attention of what ends things, not made immortal but simply no longer noticed by whatever mortality answers to.', 'The Chalice of Zςanser is never empty. It does not need to be filled. Wherever it is held, whatever its surroundings, the water of the black lake rises within it to the brim and remains there — dark, still, and cold in a way that is not quite the cold of temperature, but the cold of things that have always been outside the range of warmth.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('5aaed4d8-9259-46b4-86f3-af5b67f14de0', 'A Coroa de Aggraxæmon', 'A Coroa de Aggraxæmon não é um símbolo de autoridade, mas um motor — o processo contínuo e sem teto pelo qual ele emana cada abominação, demônio e criatura sem nome que se move pelo escuro, cada uma ligada a ele pela essência da qual foi feita.', 'A Coroa de Aggraxæmon não repousa na sua cabeça como símbolo de autoridade. Repousa lá como um motor. Dela flui o processo contínuo pelo qual Aggraxæmon produz vida — não através de união com outro, não por escolha feita num momento específico, mas como um ato contínuo de emanação, da forma como um fogo produz calor e não pode deixar de produzi-lo.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('370ed4fa-38ad-429e-9702-8f89c81b755c', 'O Véu de Ξottum', 'O Véu de Ξottum empresta ao seu portador a própria natureza de ausência de Ξottum — não ocultação, mas a condição técnica de simplesmente não se registar a nenhum sentido ou instrumento. Usá-lo é tornar-se, por um tempo, parte do domínio que já está além da percepção.', 'O Véu de Ξottum não foi feito. Emergiu dela, da forma como todas as coisas no seu domínio emergem — não produzidas, mas presentes, sem origem que possa ser rastreada. É usado, quando é usado, sem sensação. O portador não sente quando ele pousa sobre si. Ele simplesmente deixa de ser encontrável.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('ae500860-a1aa-4529-9a69-6d38adb0aa12', 'A Lente de Alveolar', 'A Lente de Alveolar refrata a compreensão, não a luz — apontada para qualquer coisa, entrega um relato completo do que ela é e como se comporta, chegando por inteiro e instantaneamente, com um peso que a maioria dos portadores descreve como o mais próximo que estiveram de deixar de ser eles mesmos.', 'A Lente de Alveolar é um círculo de matéria que não refrata a luz em nenhum sentido ordinário. O que ela refrata é a compreensão. Aponte-a para algo — qualquer coisa, qualquer sistema, qualquer estrutura — e o que chega ao entendimento do portador não é uma imagem. É um relato completo: cada dimensão, cada relação, cada número que descreve o que a coisa é e como se comporta e o que lhe acontecerá, chegando simultaneamente e plenamente formado, sem o atraso do estudo ou as lacunas da interpretação.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('478f2165-2ea0-43af-ba05-e810a715d1ca', 'O Sino de Oon', 'O Sino de Oon não toca, mas ressoa sem fim, gerando energia a partir de uma fonte ligada à própria vibração de Oon, em vez de a extrair de qualquer reserva finita — uma ressonância que os seus portadores descrevem como a confirmação de algo que sempre esteve presente sob tudo.', 'O Sino de Oon não toca. Ele ressoa — e a distinção não é trivial. Um toque é um evento. Uma ressonância é um estado. O Sino, uma vez posto em movimento, não produz um som que sobe e desce e termina. Produz uma vibração que não termina, que não diminui com a distância, que não exige o meio pelo qual o som normalmente viaja. Opera numa frequência abaixo do que os ouvidos foram feitos para processar e acima do que a matéria foi feita para resistir.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('3f32aad5-673c-42f6-824d-560a0d0d0660', 'O Cálice de Zςanser', 'O Cálice de Zςanser nunca está vazio, sempre preenchido com a água do seu lago negro — beber dele é ser subtraído da atenção daquilo que encerra as coisas, não tornando-se imortal, mas simplesmente deixando de ser notado por aquilo a que a mortalidade responde.', 'O Cálice de Zςanser nunca está vazio. Não precisa ser preenchido. Onde quer que seja segurado, quaisquer que sejam os seus arredores, a água do lago negro sobe dentro dele até a borda e ali permanece — escura, imóvel, e fria de uma forma que não é bem o frio da temperatura, mas o frio das coisas que sempre estiveram fora do alcance do calor.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('f21fc4a8-70de-4163-9329-02ef6b668a34', 'O Cetro de Slronöir', 'O Cetro de Slronöir não pode ser estudado — nenhum instrumento consegue medi-lo, e nada capaz de operar um é grande o suficiente para o ver por inteiro. Mais alto do que qualquer estrutura já construída, sustenta o Ancião, ou é simplesmente mais uma parte do que ele é, indistinguível da torre e do cadeirão em que há muito se fundiu.', 'O cetro em que Slronöir se apoia não foi estudado. Não pode ser. Nenhum instrumento calibrado para a escala do mundo conhecido é capaz de medi-lo, e nenhum ser capaz de operar tal instrumento é suficientemente grande para se aproximar do objeto com distância suficiente para vê-lo por inteiro.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('990681d1-f4e8-4db4-a368-04f72e7d70f4', 'The Sword of Ulusuros', 'The Sword of Ulusuros whispers through the air with every swing and strips its bearer of fear entirely — not courage earned through skill, but the complete absence of the mind''s capacity to calculate risk as a reason not to act. Whether this is a gift or a very specific kind of harm depends on what follows from moving, without hesitation, into something one had every reason to fear.', 'The sword appears in the legend with two properties, and both of them are strange. The first is the sharper one to explain: it whispers. Not the blade, precisely, but the air around it — every time it moves, something escapes from the passage it cuts, too quiet to be made out clearly, too consistent to be dismissed as the ordinary sound of metal through atmosphere. What the whispers say, if they say anything, is not recorded in any version of the story. The legend does not stop to listen. It moves on to what the sword does next, which is decapitate a king of giants, and the whispers are left behind in the air.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('d0f09cda-d2ee-44c4-b94e-355bf0a5a6c9', 'A Espada de Ulusuros', 'A Espada de Ulusuros sussurra pelo ar a cada golpe e retira do seu portador o medo por completo — não coragem conquistada pela habilidade, mas a ausência completa da capacidade da mente de calcular o risco como razão para não agir. Se isso é um presente ou um tipo muito específico de dano depende do que se segue de avançar, sem hesitação, em direção a algo que se tinha todas as razões para temer.', 'A espada aparece na lenda com duas propriedades, e ambas são estranhas. A primeira é a mais fácil de explicar: ela sussurra. Não a lâmina, precisamente, mas o ar ao seu redor — cada vez que se move, algo escapa da passagem que ela abre, baixo demais para ser distinguido com clareza, consistente demais para ser descartado como o som ordinário do metal cortando a atmosfera. O que os sussurros dizem, se dizem algo, não está registado em nenhuma versão da história. A lenda não para para ouvir. Avança para o que a espada faz a seguir, que é decapitar um rei dos gigantes, e os sussurros ficam para trás no ar.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('bcae6bd9-ce18-4807-ba81-804ed354d8d6', 'The Scepter of Slronöir', 'The Scepter of Slronöir cannot be studied — no instrument can measure it, and nothing capable of operating one is large enough to view it whole. Taller than any structure ever built, it holds the Ancient upright, or is simply another part of what he is, indistinguishable from the tower and the chair that have long since become him.', 'The scepter that Slronöir leans on has not been studied. It cannot be. No instrument calibrated for the scale of the known world is capable of measuring it, and no being capable of operating such an instrument is large enough to approach the thing with sufficient distance to see it whole.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('6bab2e4a-b905-4106-a9dd-cd50c363ed16', 'O Martelo de Khratøn', 'O Martelo de Khratøn traz a runa da criação numa face e a da destruição na outra, e golpeia sempre com apenas uma delas à frente — construir e destruir são, no seu golpe, a mesma força usando nomes diferentes, transformando o que quer que toque sem se importar com a direção que a transformação segue.', 'O Martelo de Khratøn é um único objeto com duas faces. Num lado da cabeça do martelo, a runa da criação está gravada fundo no metal. No outro, a runa da destruição. Elas apontam em direções opostas e nunca foram vistas ao mesmo tempo, porque o martelo, em uso, está sempre em movimento — e qualquer que seja o que ele está fazendo, está fazendo com uma face à frente.
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('d5ea4f36-b5d2-40b0-8bcb-667e2720a755', 'The Book of Black Pages', 'Nothing is known about this item.', 'Nothing is known about this item.', 'CANON', '2026-07-26 07:18:33.228805+00', '2026-07-26 07:24:34.387258+00', '48ed4b49-b7b5-4d4b-9715-00dcaa819209', NULL, 'en', 'd5ea4f36-b5d2-40b0-8bcb-667e2720a755', false);
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('9d05dfe6-01ce-4ae8-8d3f-b1186887ff3a', 'Livro de Páginas Negras', 'Nada é conhecido sobre esse item.', 'Nada é conhecido sobre esse item.', 'CANON', '2026-07-26 07:19:38.265161+00', '2026-07-26 07:24:34.667001+00', '36d5e2a5-be00-456b-bf11-113c0b737904', NULL, 'pt', 'd5ea4f36-b5d2-40b0-8bcb-667e2720a755', false);
INSERT INTO public.items (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('e6fd62e9-8c23-4fd0-a0b8-c1ad21b62ec2', 'The Hammer of Khratøn', 'The Hammer of Khratøn bears the rune of creation on one face and destruction on the other, and strikes with only one ever forward — building and breaking are, in its blow, the same force wearing different names, transforming whatever it touches without regard for which direction the transformation runs.', 'The Hammer of Khratøn is one object with two faces. On one side of the hammerhead, the rune of creation is struck deep into the metal. On the other, the rune of destruction. They face in opposite directions and have never been seen at the same time, because the hammer, in use, is always moving — and whatever it is doing, it is doing with one face forward.
