INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('47ecb08d-8306-498f-ab69-57b0e1660af1', 'We, Three Kings', 'The Triarchy of Trios is the sacred model of ideal governance, said to have been established in the holy city of Singisdônia under the blessing of Trios. Three kings — the Winged, the Golden, and the Rooted — each embody a distinct axis of rule: future, present, and past. Their decisions are made in unison, with two votes always prevailing over one, ensuring the realm is never paralysed and the interest of the many is always preserved.', 'The Triarchy of Trios is the sacred representation of ideal rule. It is written that the holy city of Singisdônia was governed by three kings, each blessed in turn by Trios himself, and that all civilisations yet to come should look upon this arrangement as the image of just governance.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('ebd1073f-0a52-4c17-86c3-bfc1cb491a22', 'The Theosophy of Aniannoth', 'The theological framework founded by scholarly priests who refused to merely believe. The Theosophy of Aniannoth classifies divine entities by the Concepts they represent — dividing gods into Outer, True, and Valkani — while acknowledging that no classification can fully contain what it describes.', 'Not every priest is a pilgrim. Among the countless faithful who repeat prayers they have never questioned, who light candles without curiosity and call on names they have never examined, there arise — rarely, in temples far from the centers of power — a different kind of mind. Not a devotee, but a scholar. Not a follower, but a student of following itself. These are the minds that look at faith as they would look at any other phenomenon worth understanding: with rigor, with doubt, and with the willingness to name what they see.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('c4ba4207-7857-49ab-8e22-5acc57ea2cd5', 'On the Word God', 'A philosophical inquiry into the concept of divinity — arguing that the word god is a valkani invention: a name large enough to hold all that exceeds mortal grasp, but never theirs to give.', 'There is no god.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('334b7fb3-31e3-4a10-a3ce-4c6afb791934', 'The Origin of Twelve', 'The goddess Dixia rules the number twelve — born from the union of Trios and Tetros, chaos and order, tricked into love by the quiet cunning of their brother Duo. She is arithmetic perfection: divisible by every ancestor in her bloodline. From her shadow, the number thirteen watches.', 'Among all numbers within infinity, none is more perfect than twelve.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('ea292de9-5429-4ecb-b821-7e1e168ffbca', 'The Twelve Aelimic Signs', 'A cosmological order, named for Ælime — goddess of love, inspiration, and order — that divides not only the people born beneath it but every energy that moves through the universe, mortal and divine alike. Four elemental Archetypes unfold into twelve Signs, each given living form in Singisdônia by one of the Twelve Original Knights. A thirteenth Sign, the Rift, stands outside this order entirely — and even it claims a knight of its own.', 'The word Aelimic descends from Ælime, the goddess of love, inspiration, and order, for it is held that no division of the world could ever be conceived without first conceiving of harmony. It is said that the order of twelve she revealed does not merely sort the people born beneath it — it sorts every energy that moves through the universe, mortal and divine alike. Those who study its origins claim it is nearly as old as Omnia itself, and that the goddess Dixia stands as a living manifestation of that very power: the number given a face, the order given breath.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('4f205e4a-01bb-4094-81c5-b49b7fe142c6', 'Sexuality of the Gods', 'A philosophical account of divine nature: the gods of Aniannoth are concepts made sovereign, not bodies. They carry no gender, are bound by no matrimonial convention, and produce offspring through the collision of living principles — or from their own substance alone.', 'The gods of Aniannoth are most commonly depicted in forms that resemble the valkani — two eyes, two hands, a body that stands upright and breathes. Yet this resemblance is a convenience, not a truth. The anthropomorphic form is a vessel chosen for legibility, a shape the mortal mind can hold without fracturing. The gods themselves are not bodies. They are concepts made sovereign. They are principles that predate the matter from which flesh is assembled.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('7bbaa3f3-0029-4679-9ba7-4f1df291c98b', 'A Origem do Doze', 'A deusa Dixia governa o número doze — nascida da união de Trios e Tetros, caos e ordem, enganados rumo ao amor pela astúcia silenciosa de seu irmão Duo. Ela é a perfeição aritmética: divisível por cada ancestral de sua linhagem. De sua sombra, o número treze observa.', 'Entre todos os números dentro do infinito, nenhum é mais perfeito que o doze.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('1c1ec59c-99f8-4184-acc2-3a1725545080', 'Nós, Três Reis', 'A Triarquia de Trios é o modelo sagrado de governança ideal, dito ter sido estabelecido na cidade sagrada de Singisdônia sob a bênção de Trios. Três reis — o Alado, o Dourado e o Enraizado — encarnam, cada um, um eixo distinto do governo: futuro, presente e passado. Suas decisões são tomadas em uníssono, com dois votos sempre prevalecendo sobre um, garantindo que o reino jamais seja paralisado e que o interesse da maioria seja sempre preservado.', 'A Triarquia de Trios é a representação sagrada do governo ideal. Está escrito que a cidade sagrada de Singisdônia foi governada por três reis, cada um abençoado por sua vez pelo próprio Trios, e que todas as civilizações ainda por vir deveriam contemplar esse arranjo como a imagem do governo justo.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('a1b2c3d4-e5f6-4789-8abc-def012345678', 'The Last Prayer', 'A teaching preserved across generations of the Omnia faith — of those who sought communion with the goddess and were never seen again, and the parable told in the temples to explain why.', '### The Parable of the Old Tree
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('acf5d45d-2163-4918-a4dd-eaac675ba44e', 'A Teosofia de Aniannoth', 'O arcabouço teológico fundado por sacerdotes eruditos que se recusaram a apenas acreditar. A Teosofia de Aniannoth classifica as entidades divinas pelos Conceitos que representam — dividindo os deuses em Externos, Verdadeiros e Valkani — reconhecendo, ainda assim, que nenhuma classificação pode conter por completo aquilo que descreve.', 'Nem todo sacerdote é um peregrino. Entre os incontáveis fiéis que repetem orações que jamais questionaram, que acendem velas sem curiosidade e invocam nomes que nunca examinaram, surge — raramente, em templos distantes dos centros de poder — um tipo diferente de mente. Não um devoto, mas um erudito. Não um seguidor, mas um estudioso do próprio ato de seguir. São essas as mentes que encaram a fé como encarariam qualquer outro fenômeno digno de compreensão: com rigor, com dúvida e com a disposição de nomear o que veem.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('86550df5-4d20-4ba8-9bc8-f0b1dfdfe420', 'The War for the Lantern of True Light', 'In the Primordial Era, Z’Mthun — a creature of dimensions beyond the absolute — waged war upon Aleph to claim the Lantern of True Light. Aleph’s middle son Verum rose in defense, built the sacred city of Singisdônia, consecrated twelve knights, and drove Z’Mthun back. Verum then became King and God of the Alephs, and through his lantern the valkani gained not merely contemplation, but the capacity to comprehend the world.', 'Not all whom Aleph’s light touches are blessed by it. Zςanser, queen of the black lake, was so dazzled by the lantern that its light burned her, waking her from her eternal rest. The veil that had covered her, a gift from her parents, proved unable to keep her hidden. Once vulnerable, Zςanser became the object of covetous desire among the Alephs and other creatures of eternity. Z’Mthun, a terrible beast and worshiper of the Absent Goddess, then waged war upon Aleph, seeking to steal his lantern. It is said that Z’Mthun was a creature of dimensions beyond the absolute, shaped from shadow and despair. From its body sprang endless monstrous soldiers — beast-warriors, devourers of gods. Any one of them alone could have brought entire universes to ruin. Now a whole army marched against the God of the Alephs.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('91165b17-3214-40b5-bbf3-0f4432905570', 'Sobre a Palavra Deus', 'Uma investigação filosófica sobre o conceito de divindade — argumentando que a palavra deus é uma invenção valkani: um nome grande o bastante para conter tudo o que excede o alcance mortal, mas que nunca foi deles para dar.', 'Não há deus.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('a8032617-5a1b-4ff9-8f65-83f08333888f', 'Os Doze Signos Aélimicos', 'Uma ordem cosmológica, nomeada em homenagem a Ælime — deusa do amor, da inspiração e da ordem — que divide não apenas os povos nascidos sob ela, mas toda energia que percorre o universo, mortal e divina por igual. Quatro Arquétipos elementais se desdobram em doze Signos, cada um dado à forma viva em Singisdônia por um dos Doze Cavaleiros Originais. Um décimo terceiro Signo, a Fenda, permanece inteiramente fora dessa ordem — e mesmo assim reivindica um cavaleiro próprio.', 'A palavra Aélimico descende de Ælime, a deusa do amor, da inspiração e da ordem, pois sustenta-se que nenhuma divisão do mundo poderia jamais ser concebida sem antes se conceber a harmonia. Diz-se que a ordem de doze que ela revelou não apenas classifica os povos nascidos sob ela — classifica toda energia que percorre o universo, mortal e divina por igual. Aqueles que estudam suas origens afirmam que é quase tão antiga quanto a própria Omnia, e que a deusa Dixia se ergue como manifestação viva desse mesmo poder: o número dado a um rosto, a ordem dada ao sopro.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('a4a55c04-a097-4350-82d2-b7b309c4d35a', 'A Última Oração', 'Um ensinamento preservado através de gerações da fé de Omnia — sobre aqueles que buscaram comunhão com a deusa e jamais foram vistos novamente, e a parábola contada nos templos para explicar o porquê.', '### A Parábola da Árvore Antiga
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('8986dc8b-69b3-4f61-bfac-1036d3ffba60', 'Sexualidade dos Deuses', 'Um relato filosófico sobre a natureza divina: os deuses de Aniannoth são conceitos tornados soberanos, não corpos. Não carregam gênero, não são vinculados a nenhuma convenção matrimonial, e geram descendência através da colisão de princípios vivos — ou apenas de sua própria substância.', 'Os deuses de Aniannoth são mais comumente retratados em formas que se assemelham aos valkani — dois olhos, duas mãos, um corpo que se ergue e respira. Mas essa semelhança é uma conveniência, não uma verdade. A forma antropomórfica é um vaso escolhido pela legibilidade, uma forma que a mente mortal pode conter sem se fraturar. Os próprios deuses não são corpos. São conceitos tornados soberanos. São princípios anteriores à matéria da qual a carne é composta.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('a96e56ee-3b1e-46dd-90f0-2818379e3531', 'A Guerra pela Lanterna da Luz Verdadeira', 'Na Era Primordial, Z''Mthun — uma criatura de dimensões além do absoluto — declarou guerra contra Aleph para reclamar a Lanterna da Luz Verdadeira. Verum, o filho do meio de Aleph, ergueu-se em defesa, construiu a cidade sagrada de Singisdônia, consagrou doze cavaleiros e repeliu Z''Mthun. Verum tornou-se então Rei e Deus dos Alephs, e através de sua lanterna os valkani ganharam não apenas a contemplação, mas a capacidade de compreender o mundo.', 'Nem todos que a luz de Aleph toca são abençoados por ela. Zςanser, rainha do lago negro, ficou tão deslumbrada pela lanterna que sua luz a queimou, despertando-a de seu repouso eterno. O véu que a cobria, um presente de seus pais, mostrou-se incapaz de mantê-la oculta. Uma vez vulnerável, Zςanser tornou-se objeto de desejo cobiçoso entre os Alephs e outras criaturas da eternidade. Z''Mthun, uma besta terrível e adoradora da Deusa Ausente, então declarou guerra contra Aleph, buscando roubar sua lanterna. Diz-se que Z''Mthun era uma criatura de dimensões além do absoluto, moldada a partir de sombra e desespero. De seu corpo brotaram infindáveis soldados monstruosos — guerreiros-bestas, devoradores de deuses. Qualquer um deles sozinho poderia ter levado universos inteiros à ruína. Agora um exército inteiro marchava contra o Deus dos Alephs.
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('521ccad8-cbe0-46ac-823b-b874bd83aba1', 'The Calling of Twelve Amets', 'The myth of how the first concepts came to drift through the primordial eternity, and of the single request — made by Imaws and Ælime to twelve of their own children — that set the entire plot of the universe into motion, for better and for far worse.', 'The Amets
INSERT INTO public.lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id, hidden) VALUES ('27ddff92-0140-42eb-889e-a0310f12ac92', 'O Chamado dos Doze Amets', 'O mito de como os primeiros conceitos vieram a vagar pela eternidade primordial, e do único pedido — feito por Imaws e Ælime a doze de seus próprios filhos — que colocou toda a trama do universo em movimento, para o bem e para um mal muito maior.', 'Os Amets
