INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('4426f1f5-1f1f-433d-a35f-080a47ab4b32', 'Communication', 'Earth', 'Diamonds', 'Business', 'Extroverted', 'Feeling', 'Selfless', 'Communication belongs to Earth and to Diamonds, the archetype of business — extroverted, governed by feeling, and selfless in nature.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'en', '4426f1f5-1f1f-433d-a35f-080a47ab4b32');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('594644a2-e7d2-41c8-91b3-f5c2789127f5', 'Might', 'Fire', 'Clubs', 'Labor', 'Extroverted', 'Sensation', 'Selfish', 'Might belongs to Fire and to Clubs, the archetype of labor — extroverted, governed by sensation, and selfish in nature.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'en', '594644a2-e7d2-41c8-91b3-f5c2789127f5');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('761d78d0-25cb-4b9b-9d6c-0d9b629f92c5', 'Cunning', 'Air', 'Spades', 'Craft', 'Introverted', 'Reason', 'Selfish', 'Cunning belongs to Air and to Spades, the archetype of craft — introverted, governed by reason, and selfish in nature.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'en', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('d3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6', 'Will', 'Water', 'Hearts', 'Mysticism', 'Introverted', 'Intuition', 'Selfless', 'Will belongs to Water and to Hearts, the archetype of mysticism — introverted, governed by intuition, and selfless in nature.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'en', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('ac88b699-f67f-44d5-95e6-41a885a1343c', 'Obsession', NULL, NULL, NULL, NULL, NULL, NULL, 'Obsession stands outside the fourfold order entirely, ruled by neither element nor suit. It backs only the Rift, the thirteenth sign, and the emptiness Obsession is forever trying, and forever failing, to fill.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'en', 'ac88b699-f67f-44d5-95e6-41a885a1343c');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Comunicação', 'Terra', 'Ouros', 'Negócios', 'Extrovertido', 'Sentimento', 'Altruísta', 'A Comunicação pertence à Terra e aos Ouros, o arquétipo dos negócios — extrovertido, governado pelo sentimento e de natureza altruísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '4426f1f5-1f1f-433d-a35f-080a47ab4b32');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Força', 'Fogo', 'Paus', 'Trabalho', 'Extrovertido', 'Sensação', 'Egoísta', 'A Força pertence ao Fogo e aos Paus, o arquétipo do trabalho — extrovertido, governado pela sensação e de natureza egoísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '594644a2-e7d2-41c8-91b3-f5c2789127f5');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Astúcia', 'Ar', 'Espadas', 'Ofício', 'Introvertido', 'Razão', 'Egoísta', 'A Astúcia pertence ao Ar e às Espadas, o arquétipo do ofício — introvertido, governado pela razão e de natureza egoísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('60f946ab-4296-46cf-8fce-88011d8c62e2', 'Vontade', 'Água', 'Copas', 'Misticismo', 'Introvertido', 'Intuição', 'Altruísta', 'A Vontade pertence à Água e às Copas, o arquétipo do misticismo — introvertido, governado pela intuição e de natureza altruísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6');
INSERT INTO public.archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('21c3575b-4681-4d81-bcfb-97a07de3bd0a', 'Obsessão', NULL, NULL, NULL, NULL, NULL, NULL, 'A Obsessão está inteiramente fora da ordem quádrupla, não sendo regida por nenhum elemento ou naipe. Ela sustenta apenas a Fenda, o décimo terceiro signo, e o vazio que a Obsessão eternamente tenta preencher, e eternamente falha em fazê-lo.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', 'ac88b699-f67f-44d5-95e6-41a885a1343c');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('285857c0-7b67-48f2-9731-cc12c77efa40', 'The Rings', 1, 'End of Spring', '4426f1f5-1f1f-433d-a35f-080a47ab4b32', 'Presence', 'Symbolizes union and protection.', 'Symbolizes union and protection. People of the sign of Rings value alliances, marriages, and connection above all else. To them, others are not merely friends or family they interact with, but an extension of themselves to be protected. They possess a natural beauty and attractiveness, offering not only emotional support but physical safety as well. They can be intimidating and imposing toward any who threaten those they love, and they are rarely someone one wishes to provoke. They take pride in this reputation, demanding displays of appreciation and cultivating their social image. They are intense lovers who bond deeply with their friends — a closeness that can be demanding in return. At the same time, they are deeply unforgiving toward betrayers or anyone who attacks their image or their loved ones. They typically settle into ordinary family roles, but may also serve as loyal protectors and guardians.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '285857c0-7b67-48f2-9731-cc12c77efa40');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('83f9d998-0160-477e-8340-429f6106a86b', 'The Tower', 2, 'Start of Summer', '594644a2-e7d2-41c8-91b3-f5c2789127f5', 'Form', 'Symbolizes toughness and robustness.', 'Symbolizes toughness and robustness. These people are pragmatic, confident executors — excellent guards, sentinels, or soldiers who trust their own strength and carry out tasks without question. Most of the Tower follow some law or order, holding to a high yet simple sense of honor, defending family, nation, or whatever they deem of equal worth. They are focused workers and fighters who pursue perfection in everything they do, and do not relent until they achieve it — after which they take pride in their accomplishment and press on toward higher ground. This is a sign of ambitious people, yet also patient and respectful ones. They want power, but want to deserve it. They want authority, but would never betray another to seize it.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '83f9d998-0160-477e-8340-429f6106a86b');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('2468c5ea-8949-4f6d-8e3a-cb86e22de590', 'The Hammer', 3, 'Middle of Summer', '594644a2-e7d2-41c8-91b3-f5c2789127f5', 'Power', 'Represents the purest form of honesty and ambition.', 'Represents the purest form of honesty and ambition. These people want power and make no secret of it. They will do whatever is necessary to obtain it, but prefer to keep everything transparent — in their minds, they are already the best, so there is no need to hide or deceive. People of the sign of the Hammer are fiercely competitive. They care little for others and openly favor a system where only the best are rewarded. They feel no shame in their craft and strive for the finest results in whatever field they find themselves. This restlessness makes them excellent manual laborers or fighters — they shine in any activity demanding repetitive or exhausting effort, building strength with ease. Disciplined and quick to learn, they also make fine soldiers. The world is simple to a person of the Hammer: they do not dwell on deep problems or philosophy. All that matters is becoming stronger and more powerful than they were yesterday. They are passionate and uncontrollable, giving everything of themselves to whatever they do. When happy, they laugh loudly. When angry, they roar like thunder.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '2468c5ea-8949-4f6d-8e3a-cb86e22de590');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('ebd973da-6df0-4820-bb76-65fc71257329', 'The Hood', 4, 'End of Summer', '594644a2-e7d2-41c8-91b3-f5c2789127f5', 'Skill', 'Represents the excellence of practice.', 'Represents the excellence of practice. People of this sign are at once sharp and humble. They pursue personal achievement in the world, seeking to be the best at what they do without dragging anyone else into that pursuit. Their struggle is only against themselves, and they rarely display it openly. Even so, they become references in their field and inevitably attract attention. They do not reject fame — it is simply another tool for their ascent — but neither do they bask in it. Recognition, to them, is merely another step toward perfection, which is the only true reward they seek. They excel as martial artists, athletes, marksmen, and other practitioners of focus and precision, never tiring of refining their technique. Beneath this, they are sly individuals, bringing their sharpness into their personalities, forever measuring others against themselves in their minds. They can be envious, but rarely act upon it — more often, they turn that admiration into motivation.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'ebd973da-6df0-4820-bb76-65fc71257329');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('889afafc-a095-461c-9e2c-1ae103591948', 'The Mask', 5, 'Start of Fall', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5', 'Guile', 'Symbolizes cleverness and ingenuity.', 'Symbolizes cleverness and ingenuity. These are the ones who find the easy way out. They despise effort and see no virtue in making life harder than it must be. People of the sign of the Mask may be found tricking others through schemes and scams, but may equally be shrewd merchants or businessmen who find the loopholes in any system and profit from them. They are not necessarily dishonest, but they are skilled in trickery and deception, possessing a flexible sense of morality and quick thinking. Placed under pressure, they will not hesitate to bend the system and use whatever means necessary to improve their situation. Yet in comfortable circumstances, these same people make the most effective allies or employees one could ask for, since they value their position and reward it in kind. The Mask is not immune to guilt — they simply do not dwell on it. They see the world as the hard place it is, believing everyone steps on someone else to get by, and they are no exception. If they do not do it, someone else will — and in their view, they cause the least harm possible along the way. All they want is a better life for themselves, not the ruin of others.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '889afafc-a095-461c-9e2c-1ae103591948');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('f4ff1720-96c8-4736-80c0-9a05b02e3ea6', 'The Lantern', 6, 'Middle of Fall', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5', 'Vision', 'Represents guidance and wisdom.', 'Represents guidance and wisdom. People of this sign are the finest teachers and the most deserving of leadership, though they often refuse positions of authority, feeling unworthy or lacking the ambition to claim them. They are gifted strategists who attract followers naturally through their brilliance. These people are always looking beyond what others see — pondering the world''s problems and seeking solutions to matters most people never consider. They rarely act on these insights themselves, however; they are far better at pointing the way than walking it. They love philosophy and find pleasure in travel and the exploration of new places, ever searching — in mind and body alike — for universal truth.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'f4ff1720-96c8-4736-80c0-9a05b02e3ea6');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('49112518-7835-422c-9587-9d80060980c0', 'The Lens', 7, 'End of Fall', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5', 'Curiosity', 'Represents the pursuit of knowledge through study.', 'Represents the pursuit of knowledge through study. People of this sign make the finest craftsmen and scientists, skilled at following method, exploring disciplines, and designing solutions to all manner of problems. The Lens is pragmatic by nature, believing the world holds a correct order, and that to follow it is to set things right. They struggle to understand opinions or mentalities unlike their own. They tend to be highly organized, tidy, and self-sufficient, often never marrying or raising children. Though they hold a deep curiosity for what they learn, they require no profound reasoning behind it — they are content to know how something works without needing to know why. They are also skilled caretakers of plants, animals, buildings, and structures alike.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '49112518-7835-422c-9587-9d80060980c0');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('96cc8ec0-0d3a-4119-8afa-d826b638ac30', 'The Gold', 8, 'Start of Winter', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6', 'Passion', 'Represents talent and gift.', 'Represents talent and gift. People of this sign carry a calling toward some highly specific skill, which they embody and perform with an excellence that astonishes all who witness it. They make the finest artificers, though their talent may manifest in any pursuit. This does not mean they require no training — only that they experience their training as joyful and fulfilling rather than exhausting labor. People of the Gold sign are calm and courteous, rarely displaying strong emotion, and seem to hold everything under quiet control. Outside of their craft, they can appear inexpressive — but once engaged with their talent, they become the center of attention almost instantly. They may fall into laziness, since so much comes easily to them, yet they refuse to be made a spectacle or experiment for those who would push them too far.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '96cc8ec0-0d3a-4119-8afa-d826b638ac30');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('a6675b83-ef16-49e5-878a-e0c5e7b823fa', 'The Chalice', 9, 'Middle of Winter', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6', 'Devotion', 'Represents complete and selfless devotion.', 'Represents complete and selfless devotion. People of this sign are vessels for something greater than themselves — perfect priests, or simply perfect followers. They act on behalf of a cause and pour their entire being into it, and others perceive a purity in their actions, a holiness in their devotion. The Chalice is deeply nurturing yet strangely empty, as though possessing no personality wholly their own. They rarely speak of their own lives or struggles, but when they do, it is with reverence, grace, and an unshakable optimism. They accept the world as it is, seeking neither answers nor solutions for it, choosing instead to meet it with patience, guiding others toward the path of least conflict. They are dreamers, drawn deeply to the occult, gifted with strong intuition — often sensing when something is about to go right or wrong — and given to superstition.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'a6675b83-ef16-49e5-878a-e0c5e7b823fa');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('b669a183-9c01-4a57-ba6d-389d97bb1ca8', 'The Bell', 10, 'End of Winter', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6', 'Tuning', 'Represents empathy and connection.', 'Represents empathy and connection. People of this sign understand and engage with the emotions of others with ease, evoking feelings in those around them without effort. Naturally seductive, they can be either inspiring or unsettling. Though often aloof, they are perceived as fortunate and easy to love. They move through life with no great ambitions, yet things always seem to work out for them. Easily pleased, they do not chase refinement, yet often achieve it regardless, surrounding themselves with a splendor that others envy. They work poorly within rules and will always test them — not from rebellion, but as a form of expression. They feel what others feel and, without meaning to, make others feel differently in turn. They can sense lies and deceit, though they could never explain how.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'b669a183-9c01-4a57-ba6d-389d97bb1ca8');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('0394b7de-e1bd-447e-9f38-faf24782c378', 'The Mirror', 11, 'Start of Spring', '4426f1f5-1f1f-433d-a35f-080a47ab4b32', 'Persuasion', 'Represents manipulation and diplomacy at their finest.', 'Represents manipulation and diplomacy at their finest. People of this sign view others as assets, living to influence and to build their own image. Naturally friendly, they raise the morale of those around them with ease, reading and shaping behavior as it suits them. Ideal as politicians, merchants, gamblers, or spies. They do not believe in universal truth, holding instead that everything is a matter of opinion — their preferences are volatile, caring little for any particular outcome so long as it satisfies the majority. They can be deeply indecisive, preferring to follow another''s direction on complex matters rather than choose one themselves. They lack a personal sense of purpose, filling that absence instead with the goals of their group or society. They read faces and body language as if reading an open book, and know precisely how to provoke or entice.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', '0394b7de-e1bd-447e-9f38-faf24782c378');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('cac54126-d160-41f6-aa93-da760505d57a', 'The Crown', 12, 'Middle of Spring', '4426f1f5-1f1f-433d-a35f-080a47ab4b32', 'Communion', 'Symbolizes leadership and rule.', 'Symbolizes leadership and rule. People of this sign are well-spoken, valuing interpersonal connection and conversation above most things — ideal as rulers and managers. They possess a natural charisma and a gift for oratory and command; when they speak, others listen. They care deeply about unity and solidarity, and it shows in everything they do. They love to coordinate groups, inspire motivation, and direct others toward the right path — though they are not always certain, themselves, what that path is. They always project confidence and always seem to know what to say, even when speaking of matters they barely understand. The Crown despises solitude and loves routine, rarely ceasing their work and seldom traveling unless others wish it. They take little pleasure in gatherings, yet attend them all the same, valuing them as opportunities for connection.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'cac54126-d160-41f6-aa93-da760505d57a');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('bafd608a-31bd-48b3-bcb6-6ec61c42e5a4', 'The Rift', 13, 'The off-season days — those that fall outside the count of the four seasons, the "leftover" days of the year', 'ac88b699-f67f-44d5-95e6-41a885a1343c', NULL, 'Marks an emptiness at the center of one''s being — a void its bearers spend their whole life trying to fill, and never will.', 'It is said that on certain days and nights, a person may be born outside any of the Twelve Signs. It is no simple matter to determine which exact hour, of which exact day, will produce a child of the Rift, for its influence is spread thin across the entire year. And yet they are born, and they carry a troubled nature. The Rift marks an emptiness at the center of one''s being — a void they will spend their whole life trying to fill, and never will. They hold no real sense of society, no morals, and no true motivation. They will seek everything: attention, praise, worth, and power, yet never be satisfied by any of it. They care nothing for emotion or reason, for meaning or growth. They will always stir destruction, either by trying to consume everything into their possession, or by reducing everything around them to the same void they themselves inhabit. Those born under the Rift are victims as much as they are dangers — to be approached with caution, but also with compassion. Their endless hunger drives them to levels of ability unmatched by any other sign; their willingness for sacrifice may carry them further than anyone else could go. They are capable of extraordinary things, but will always operate beyond the natural limits of the world. They must be stopped — and yet, it is such a pity.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'en', 'bafd608a-31bd-48b3-bcb6-6ec61c42e5a4');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('023f34b4-9899-473c-8ce7-2ceb6a3c858d', 'Os Anéis', 1, 'Fim da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Presença', 'Simboliza união e proteção.', 'Simboliza união e proteção. As pessoas do signo dos Anéis valorizam alianças, casamentos e conexão acima de tudo. Para elas, os outros não são apenas amigos ou familiares com quem interagem, mas uma extensão de si mesmas a ser protegida. Possuem uma beleza e um magnetismo naturais, oferecendo não apenas apoio emocional, mas também segurança física. Podem ser intimidadoras e impositivas com quem quer que ameace aqueles que amam, e raramente são alguém que se deseja provocar. Orgulham-se dessa reputação, exigindo demonstrações de apreço e cultivando sua imagem social. São amantes intensos que se ligam profundamente a seus amigos — uma proximidade que pode ser exigente em retorno. Ao mesmo tempo, são profundamente implacáveis com traidores ou com qualquer um que ataque sua imagem ou seus entes queridos. Costumam se estabelecer em papéis familiares comuns, mas também podem servir como protetores e guardiões leais.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '285857c0-7b67-48f2-9731-cc12c77efa40');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('eda70aa5-5de9-4013-a330-5849db9f0071', 'A Torre', 2, 'Início do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Forma', 'Simboliza resistência e robustez.', 'Simboliza resistência e robustez. Essas pessoas são executoras pragmáticas e confiantes — excelentes guardas, sentinelas ou soldados que confiam na própria força e cumprem tarefas sem questionar. A maioria dos da Torre segue alguma lei ou ordem, mantendo um senso de honra elevado, porém simples, defendendo a família, a nação, ou o que quer que considerem de igual valor. São trabalhadores e lutadores focados que buscam a perfeição em tudo o que fazem, e não relaxam até alcançá-la — após o que se orgulham de sua conquista e seguem em frente rumo a patamares mais altos. Este é um signo de pessoas ambiciosas, mas também pacientes e respeitosas. Querem poder, mas querem merecê-lo. Querem autoridade, mas jamais trairiam outrem para conquistá-la.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '83f9d998-0160-477e-8340-429f6106a86b');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('24939216-46bd-4251-b3a9-f826c330aad4', 'O Cálice', 9, 'Meio do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Devoção', 'Representa devoção completa e altruísta.', 'Representa devoção completa e altruísta. As pessoas deste signo são vasos para algo maior que si mesmas — sacerdotisas perfeitas, ou simplesmente seguidoras perfeitas. Agem em nome de uma causa e derramam todo o seu ser nela, e os outros percebem uma pureza em suas ações, uma santidade em sua devoção. O Cálice é profundamente acolhedor, mas estranhamente vazio, como se não possuísse uma personalidade inteiramente própria. Raramente falam de suas próprias vidas ou lutas, mas, quando o fazem, é com reverência, graça e um otimismo inabalável. Aceitam o mundo como ele é, não buscando respostas nem soluções para ele, escolhendo em vez disso enfrentá-lo com paciência, guiando os outros rumo ao caminho de menor conflito. São sonhadoras, profundamente atraídas pelo oculto, dotadas de forte intuição — muitas vezes sentindo quando algo está prestes a dar certo ou errado — e propensas à superstição.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'a6675b83-ef16-49e5-878a-e0c5e7b823fa');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('20bb7195-79d1-4039-9040-49225fe6f877', 'O Martelo', 3, 'Meio do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Poder', 'Representa a forma mais pura de honestidade e ambição.', 'Representa a forma mais pura de honestidade e ambição. Essas pessoas querem poder e não fazem segredo disso. Farão o que for necessário para obtê-lo, mas preferem manter tudo transparente — em suas mentes, já são as melhores, então não há necessidade de se esconder ou enganar. As pessoas do signo do Martelo são ferozmente competitivas. Preocupam-se pouco com os outros e favorecem abertamente um sistema em que apenas os melhores são recompensados. Não sentem vergonha de seu ofício e buscam os melhores resultados em qualquer campo em que se encontrem. Essa inquietação as torna excelentes trabalhadoras braçais ou lutadoras — brilham em qualquer atividade que exija esforço repetitivo ou exaustivo, construindo força com facilidade. Disciplinadas e rápidas para aprender, também são boas soldadas. O mundo é simples para uma pessoa do Martelo: ela não se detém em problemas profundos ou filosofia. Tudo o que importa é se tornar mais forte e mais poderosa do que era ontem. São apaixonadas e incontroláveis, entregando tudo de si naquilo que fazem. Quando felizes, riem alto. Quando irritadas, rugem como trovões.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '2468c5ea-8949-4f6d-8e3a-cb86e22de590');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('e10d0e63-f51a-4344-8a07-e2c877fc9378', 'O Capuz', 4, 'Fim do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Habilidade', 'Representa a excelência da prática.', 'Representa a excelência da prática. As pessoas deste signo são ao mesmo tempo perspicazes e humildes. Buscam realização pessoal no mundo, procurando ser as melhores naquilo que fazem sem arrastar ninguém mais para essa busca. Sua luta é apenas contra si mesmas, e raramente a exibem abertamente. Ainda assim, tornam-se referências em seu campo e inevitavelmente atraem atenção. Não rejeitam a fama — ela é apenas mais uma ferramenta para sua ascensão —, mas também não se deleitam nela. O reconhecimento, para elas, é apenas mais um passo rumo à perfeição, que é a única recompensa verdadeira que buscam. Destacam-se como artistas marciais, atletas, atiradoras e outras praticantes de foco e precisão, nunca se cansando de refinar sua técnica. Por trás disso, são indivíduos astutos, levando sua perspicácia para suas personalidades, sempre medindo os outros contra si mesmas em suas mentes. Podem sentir inveja, mas raramente agem a partir dela — mais frequentemente, transformam essa admiração em motivação.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'ebd973da-6df0-4820-bb76-65fc71257329');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('54913dcc-d0e7-467b-b3d9-81d9059ebbc8', 'A Máscara', 5, 'Início do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Ardil', 'Simboliza inteligência e engenhosidade.', 'Simboliza inteligência e engenhosidade. São aqueles que encontram o caminho mais fácil. Desprezam o esforço e não veem virtude em tornar a vida mais difícil do que precisa ser. As pessoas do signo da Máscara podem ser encontradas enganando outros por meio de esquemas e golpes, mas podem igualmente ser mercadoras ou empresárias astutas que encontram brechas em qualquer sistema e lucram com elas. Não são necessariamente desonestas, mas são hábeis em trapaça e engano, possuindo um senso de moralidade flexível e um raciocínio rápido. Sob pressão, não hesitarão em dobrar o sistema e usar todos os meios necessários para melhorar sua situação. No entanto, em circunstâncias confortáveis, essas mesmas pessoas se tornam os aliados ou funcionários mais eficazes que se poderia pedir, já que valorizam sua posição e a recompensam na mesma moeda. A Máscara não é imune à culpa — simplesmente não se detém nela. Vê o mundo como o lugar difícil que ele é, acreditando que todos pisam em alguém para sobreviver, e não são exceção. Se não o fizerem, outro o fará — e, em sua visão, causam o menor dano possível ao longo do caminho. Tudo o que querem é uma vida melhor para si mesmas, não a ruína dos outros.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '889afafc-a095-461c-9e2c-1ae103591948');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('d1cf7fbe-5dd3-4c2e-86f5-b99b1fb976ec', 'A Lanterna', 6, 'Meio do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Visão', 'Representa orientação e sabedoria.', 'Representa orientação e sabedoria. As pessoas deste signo são as melhores professoras e as mais merecedoras de liderança, embora muitas vezes recusem posições de autoridade, sentindo-se indignas ou sem a ambição de reivindicá-las. São estrategistas talentosas que atraem seguidores naturalmente por meio de seu brilhantismo. Essas pessoas estão sempre enxergando além do que os outros veem — ponderando os problemas do mundo e buscando soluções para questões que a maioria nunca considera. Raramente, porém, agem sobre essas percepções; são muito melhores em apontar o caminho do que em percorrê-lo. Amam a filosofia e encontram prazer em viajar e explorar novos lugares, sempre em busca — na mente e no corpo — da verdade universal.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'f4ff1720-96c8-4736-80c0-9a05b02e3ea6');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('3e8b6e1a-b9e4-4e22-94b5-af36c6838738', 'A Lente', 7, 'Fim do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Curiosidade', 'Representa a busca pelo conhecimento através do estudo.', 'Representa a busca pelo conhecimento através do estudo. As pessoas deste signo são os melhores artesãos e cientistas, hábeis em seguir métodos, explorar disciplinas e conceber soluções para todo tipo de problema. A Lente é pragmática por natureza, acreditando que o mundo possui uma ordem correta, e que segui-la é colocar as coisas nos eixos. Têm dificuldade em compreender opiniões ou mentalidades diferentes das suas. Tendem a ser altamente organizadas, arrumadas e autossuficientes, muitas vezes nunca se casando ou criando filhos. Embora tenham uma curiosidade profunda pelo que aprendem, não precisam de um raciocínio profundo por trás disso — contentam-se em saber como algo funciona sem precisar saber por quê. São também cuidadoras habilidosas de plantas, animais, edifícios e estruturas.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '49112518-7835-422c-9587-9d80060980c0');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('aa2cc57b-92c3-4a76-8e7d-9484a07c10d8', 'O Ouro', 8, 'Início do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Paixão', 'Representa talento e dom.', 'Representa talento e dom. As pessoas deste signo carregam um chamado para alguma habilidade altamente específica, que incorporam e executam com uma excelência que espanta a todos que a testemunham. São as melhores artífices, embora seu talento possa se manifestar em qualquer atividade. Isso não significa que dispensem treinamento — apenas que vivenciam seu treinamento como algo alegre e gratificante, e não como um trabalho exaustivo. As pessoas do signo do Ouro são calmas e corteses, raramente exibindo emoções fortes, e parecem manter tudo sob um controle silencioso. Fora de seu ofício, podem parecer inexpressivas — mas, uma vez engajadas com seu talento, tornam-se o centro das atenções quase instantaneamente. Podem cair na preguiça, já que tanto lhes vem com facilidade, mas se recusam a se tornar espetáculo ou experimento para quem as pressionar demais.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '96cc8ec0-0d3a-4119-8afa-d826b638ac30');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('48e68a23-0d30-4f46-8123-463f60daca4b', 'O Sino', 10, 'Fim do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Afinação', 'Representa empatia e conexão.', 'Representa empatia e conexão. As pessoas deste signo compreendem e se conectam com as emoções alheias com facilidade, evocando sentimentos nos que as cercam sem esforço. Naturalmente sedutoras, podem ser tanto inspiradoras quanto perturbadoras. Embora muitas vezes distantes, são percebidas como afortunadas e fáceis de amar. Movem-se pela vida sem grandes ambições, e ainda assim as coisas sempre parecem se resolver a seu favor. Facilmente satisfeitas, não perseguem o refinamento, mas frequentemente o alcançam de qualquer forma, cercando-se de um esplendor que os outros invejam. Trabalham mal dentro de regras e sempre as testarão — não por rebeldia, mas como forma de expressão. Sentem o que os outros sentem e, sem querer, fazem os outros sentirem de forma diferente. Conseguem perceber mentiras e enganos, embora jamais consigam explicar como.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'b669a183-9c01-4a57-ba6d-389d97bb1ca8');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('8d339dcc-7405-4a2d-878b-fbfe7dd40820', 'O Espelho', 11, 'Início da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Persuasão', 'Representa manipulação e diplomacia em seu ápice.', 'Representa manipulação e diplomacia em seu ápice. As pessoas deste signo veem os outros como recursos, vivendo para influenciar e construir sua própria imagem. Naturalmente amistosas, elevam o moral dos que as cercam com facilidade, lendo e moldando comportamentos como lhes convém. Ideais como políticas, mercadoras, apostadoras ou espiãs. Não acreditam em verdade universal, sustentando em vez disso que tudo é questão de opinião — suas preferências são voláteis, importando-se pouco com qualquer resultado específico, desde que satisfaça a maioria. Podem ser profundamente indecisas, preferindo seguir a direção de outrem em assuntos complexos a escolher uma própria. Carecem de um senso de propósito pessoal, preenchendo essa ausência com os objetivos de seu grupo ou sociedade. Leem rostos e linguagem corporal como quem lê um livro aberto, e sabem precisamente como provocar ou seduzir.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '0394b7de-e1bd-447e-9f38-faf24782c378');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('258c3c13-99d1-481e-8613-b36fd1ff188c', 'A Coroa', 12, 'Meio da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Comunhão', 'Simboliza liderança e governo.', 'Simboliza liderança e governo. As pessoas deste signo são bem articuladas, valorizando a conexão interpessoal e a conversa acima da maioria das coisas — ideais como governantes e gestoras. Possuem um carisma natural e um dom para a oratória e o comando; quando falam, os outros escutam. Preocupam-se profundamente com a unidade e a solidariedade, e isso transparece em tudo o que fazem. Adoram coordenar grupos, inspirar motivação e direcionar os outros rumo ao caminho certo — embora nem sempre tenham certeza, elas mesmas, de qual seja esse caminho. Sempre projetam confiança e sempre parecem saber o que dizer, mesmo ao falar de assuntos que mal compreendem. A Coroa despreza a solidão e adora a rotina, raramente cessando seu trabalho e raramente viajando a menos que outros o desejem. Sentem pouco prazer em reuniões sociais, mas ainda assim comparecem, valorizando-as como oportunidades de conexão.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'cac54126-d160-41f6-aa93-da760505d57a');
INSERT INTO public.signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('c523932f-bfea-4807-931b-4c90fc0f18e4', 'A Fenda', 13, 'Os dias fora de estação — aqueles que caem fora da contagem das quatro estações, os dias ‘excedentes’ do ano', '21c3575b-4681-4d81-bcfb-97a07de3bd0a', NULL, 'Marca um vazio no centro do próprio ser — um vazio que seus portadores passam a vida inteira tentando preencher, e nunca conseguirão.', 'Diz-se que, em certos dias e noites, uma pessoa pode nascer fora de qualquer um dos Doze Signos. Não é tarefa simples determinar qual hora exata, de qual dia exato, produzirá um filho da Fenda, pois sua influência se espalha tenuemente por todo o ano. E, ainda assim, eles nascem, e carregam uma natureza perturbada. A Fenda marca um vazio no centro do próprio ser — um vazio que passarão a vida inteira tentando preencher, e nunca conseguirão. Não possuem um senso real de sociedade, nem moral, nem motivação verdadeira. Buscarão tudo: atenção, elogio, valor e poder, mas jamais serão satisfeitos por qualquer um deles. Não se importam com emoção ou razão, com significado ou crescimento. Sempre provocarão destruição, seja tentando consumir tudo para si, seja reduzindo tudo ao seu redor ao mesmo vazio que eles próprios habitam. Aqueles nascidos sob a Fenda são vítimas tanto quanto são perigos — a serem abordados com cautela, mas também com compaixão. Sua fome infindável os impulsiona a níveis de habilidade sem igual entre os demais signos; sua disposição para o sacrifício pode levá-los mais longe do que qualquer outro poderia ir. São capazes de coisas extraordinárias, mas sempre operarão além dos limites naturais do mundo. Precisam ser detidos — e, ainda assim, que pena.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'bafd608a-31bd-48b3-bcb6-6ec61c42e5a4');
